const CONV = [{"id":"d_rent_room","dom":"daily","lv":3,"title":{"zh":"租房間","id":"Menyewa kamar","en":"Renting a room"},"goal":{"id":"Setelah ini kamu bisa menanyakan harga sewa, deposit, dan fasilitas kamar kepada pemilik kos."},"lines":[{"sp":"A","zh":"你好，請問這間套房還有在租嗎？","py":"nǐ hǎo qǐng wèn zhè jiān tào fáng hái yǒu zài zū ma","id":"Halo, permisi, kamar ini masih disewakan?","en":"Hi, is this studio still for rent?"},{"sp":"B","zh":"有啊，一個月六千五，水電另外算。","py":"yǒu a yí ge yuè liù qiān wǔ shuǐ diàn lìng wài suàn","id":"Ada, 6.500 per bulan, listrik dan air dihitung terpisah.","en":"Yes, 6,500 a month, with water and electricity charged separately."},{"sp":"A","zh":"有冷氣和洗衣機嗎？","py":"yǒu lěng qì hé xǐ yī jī ma","id":"Ada AC dan mesin cuci?","en":"Does it have air conditioning and a washing machine?"},{"sp":"B","zh":"冷氣有，洗衣機在頂樓，大家共用。","py":"lěng qì yǒu xǐ yī jī zài dǐng lóu dà jiā gòng yòng","id":"AC ada, mesin cuci ada di lantai atas, dipakai bersama.","en":"There is AC. The washing machine is on the top floor, shared by everyone."},{"sp":"A","zh":"押金要付多少？","py":"yā jīn yào fù duō shǎo","id":"Deposit-nya berapa?","en":"How much is the deposit?"},{"sp":"B","zh":"押金兩個月，租約要簽一年。","py":"yā jīn liǎng ge yuè zū yuē yào qiān yì nián","id":"Deposit dua bulan, kontraknya harus satu tahun.","en":"Two months' deposit, and the lease is for one year."},{"sp":"A","zh":"我是外籍學生，可以先看房間再決定嗎？","py":"wǒ shì wài jí xué shēng kě yǐ xiān kàn fáng jiān zài jué dìng ma","id":"Saya mahasiswa asing, boleh lihat kamarnya dulu baru memutuskan?","en":"I'm an international student. Can I see the room first and then decide?"},{"sp":"B","zh":"當然可以，我現在帶你上去看。","py":"dāng rán kě yǐ wǒ xiàn zài dài nǐ shàng qù kàn","id":"Tentu boleh, saya antar naik sekarang.","en":"Of course. I'll take you up to see it now."},{"sp":"A","zh":"房間很乾淨。可是網路要另外申請嗎？","py":"fáng jiān hěn gān jìng kě shì wǎng lù yào lìng wài shēn qǐng ma","id":"Kamarnya bersih. Tapi internetnya harus daftar sendiri?","en":"The room is clean. But do I need to apply for internet separately?"},{"sp":"B","zh":"不用，網路已經包在房租裡了。","py":"bú yòng wǎng lù yǐ jīng bāo zài fáng zū lǐ le","id":"Tidak perlu, internet sudah termasuk dalam uang sewa.","en":"No need, internet is already included in the rent."},{"sp":"A","zh":"太好了，那我考慮一下，明天再跟你聯絡。","py":"tài hǎo le nà wǒ kǎo lǜ yí xià míng tiān zài gēn nǐ lián luò","id":"Bagus, saya pertimbangkan dulu, besok saya hubungi lagi.","en":"Great, let me think about it and I'll get back to you tomorrow."},{"sp":"B","zh":"好，沒問題。","py":"hǎo méi wèn tí","id":"Baik, tidak masalah.","en":"Sure, no problem."}],"phrases":[{"zh":"還有在租嗎","py":"hái yǒu zài zū ma","id":"masih disewakan?"},{"zh":"水電另外算","py":"shuǐ diàn lìng wài suàn","id":"listrik dan air dihitung terpisah"},{"zh":"押金","py":"yā jīn","id":"uang jaminan (deposit)"},{"zh":"包在房租裡","py":"bāo zài fáng zū lǐ","id":"sudah termasuk dalam uang sewa"},{"zh":"我考慮一下","py":"wǒ kǎo lǜ yí xià","id":"saya pikirkan dulu"}],"grammar":["ma","zai","le"],"task":{"id":"Kamu sedang mencari kos. Tanyakan harga, deposit, dan fasilitas (AC, internet) kepada pemilik, lalu katakan bahwa kamu akan memberi kabar besok."}},{"id":"d_pay_bills_convenience_store","dom":"daily","lv":3,"title":{"zh":"便利商店繳費取貨","id":"Bayar tagihan dan ambil paket di minimarket","en":"Paying bills and picking up a parcel"},"goal":{"id":"Setelah ini kamu bisa membayar tagihan listrik dan air serta mengambil paket di minimarket."},"lines":[{"sp":"A","zh":"你好，我要繳電費。","py":"nǐ hǎo wǒ yào jiǎo diàn fèi","id":"Halo, saya mau bayar tagihan listrik.","en":"Hi, I'd like to pay my electricity bill."},{"sp":"B","zh":"可以，請把繳費單給我。","py":"kě yǐ qǐng bǎ jiǎo fèi dān gěi wǒ","id":"Boleh, tolong berikan slip tagihannya.","en":"Sure, please give me the bill."},{"sp":"A","zh":"在這裡。還有這張水費單。","py":"zài zhè lǐ hái yǒu zhè zhāng shuǐ fèi dān","id":"Ini. Dan ini tagihan air.","en":"Here it is. And this water bill too."},{"sp":"B","zh":"電費一千兩百三十元，水費四百二十元，一共一千六百五十元。","py":"diàn fèi yì qiān liǎng bǎi sān shí yuán shuǐ fèi sì bǎi èr shí yuán yì gòng yì qiān liù bǎi wǔ shí yuán","id":"Listrik 1.230, air 420, totalnya 1.650 dolar Taiwan.","en":"Electricity is 1,230, water is 420, so 1,650 in total."},{"sp":"A","zh":"我可以用一卡通付嗎？","py":"wǒ kě yǐ yòng yì kǎ tōng fù ma","id":"Boleh bayar pakai kartu iPass?","en":"Can I pay with my iPass card?"},{"sp":"B","zh":"繳費只能付現金喔。","py":"jiǎo fèi zhǐ néng fù xiàn jīn o","id":"Bayar tagihan hanya bisa tunai ya.","en":"Bill payments are cash only."},{"sp":"A","zh":"好，這是兩千元。","py":"hǎo zhè shì liǎng qiān yuán","id":"Baik, ini 2.000.","en":"OK, here's 2,000."},{"sp":"B","zh":"找你三百五十元，這是收據，請收好。","py":"zhǎo nǐ sān bǎi wǔ shí yuán zhè shì shōu jù qǐng shōu hǎo","id":"Kembaliannya 350, ini bukti pembayaran, tolong disimpan.","en":"Here's 350 in change and your receipt. Please keep it."},{"sp":"A","zh":"對了，我有一個網購的包裹要取貨。","py":"duì le wǒ yǒu yí ge wǎng gòu de bāo guǒ yào qǔ huò","id":"Oh ya, saya ada paket belanja online yang mau diambil.","en":"By the way, I have an online order to pick up."},{"sp":"B","zh":"請給我取貨編號或手機條碼。","py":"qǐng gěi wǒ qǔ huò biān hào huò shǒu jī tiáo mǎ","id":"Tolong berikan nomor pengambilan atau barcode di ponsel.","en":"Please give me the pickup number or the barcode on your phone."},{"sp":"A","zh":"手機條碼在這裡。","py":"shǒu jī tiáo mǎ zài zhè lǐ","id":"Barcode di ponsel ada di sini.","en":"The barcode is right here on my phone."},{"sp":"B","zh":"好，這是你的包裹，請在這裡簽名。","py":"hǎo zhè shì nǐ de bāo guǒ qǐng zài zhè lǐ qiān míng","id":"Baik, ini paketnya, silakan tanda tangan di sini.","en":"OK, here's your parcel. Please sign here."}],"phrases":[{"zh":"繳電費","py":"jiǎo diàn fèi","id":"bayar tagihan listrik"},{"zh":"收據請收好","py":"shōu jù qǐng shōu hǎo","id":"tolong simpan struknya"},{"zh":"只能付現金","py":"zhǐ néng fù xiàn jīn","id":"hanya bisa bayar tunai"},{"zh":"取貨","py":"qǔ huò","id":"ambil paket"},{"zh":"請在這裡簽名","py":"qǐng zài zhè lǐ qiān míng","id":"tolong tanda tangan di sini"}],"grammar":["ba","zai","mw"],"task":{"id":"Kamu membawa tagihan listrik dan air ke minimarket. Bayar dengan tunai, minta bukti pembayaran, lalu ambil paketmu."}},{"id":"d_bubble_tea_order","dom":"daily","lv":3,"title":{"zh":"點珍珠奶茶","id":"Memesan bubble tea","en":"Ordering bubble tea"},"goal":{"id":"Setelah ini kamu bisa memesan minuman dengan mengatur ukuran, tingkat manis, es, dan topping."},"lines":[{"sp":"A","zh":"你好，我要一杯珍珠奶茶。","py":"nǐ hǎo wǒ yào yì bēi zhēn zhū nǎi chá","id":"Halo, saya mau satu gelas boba milk tea.","en":"Hi, I'd like a bubble milk tea."},{"sp":"B","zh":"好，請問要大杯還是中杯？","py":"hǎo qǐng wèn yào dà bēi hái shì zhōng bēi","id":"Baik, mau ukuran besar atau sedang?","en":"Sure, large or medium?"},{"sp":"A","zh":"大杯，半糖。","py":"dà bēi bàn táng","id":"Besar, setengah gula.","en":"Large, half sugar."},{"sp":"B","zh":"好，冰塊呢？正常冰、少冰、微冰、去冰都可以。","py":"hǎo bīng kuài ne zhèng cháng bīng shǎo bīng wéi bīng qù bīng dōu kě yǐ","id":"Oke, esnya? Normal, sedikit, sangat sedikit, atau tanpa es, semua bisa.","en":"OK, and ice? Regular, less, light, or no ice are all fine."},{"sp":"A","zh":"少冰，謝謝。可以加椰果嗎？","py":"shǎo bīng xiè xie kě yǐ jiā yē guǒ ma","id":"Es sedikit, terima kasih. Boleh tambah nata de coco?","en":"Less ice, thanks. Can I add coconut jelly?"},{"sp":"B","zh":"可以，加椰果多五塊喔。","py":"kě yǐ jiā yē guǒ duō wǔ kuài o","id":"Boleh, tambah nata de coco lebih lima dolar ya.","en":"Sure, adding coconut jelly is five dollars extra."},{"sp":"A","zh":"沒關係，那我還要一杯無糖綠茶，去冰。","py":"méi guān xi nà wǒ hái yào yì bēi wú táng lǜ chá qù bīng","id":"Tidak apa-apa, saya juga mau satu teh hijau tanpa gula, tanpa es.","en":"That's fine. I'd also like an unsweetened green tea with no ice."},{"sp":"B","zh":"一共九十五元，內用還是外帶？","py":"yì gòng jiǔ shí wǔ yuán nèi yòng hái shì wài dài","id":"Totalnya 95, makan di sini atau dibawa pulang?","en":"That's 95 in total. For here or to go?"},{"sp":"A","zh":"外帶。可以用行動支付嗎？","py":"wài dài kě yǐ yòng xíng dòng zhī fù ma","id":"Dibawa pulang. Boleh bayar pakai dompet digital?","en":"To go. Can I pay with mobile payment?"},{"sp":"B","zh":"可以，請掃這裡。","py":"kě yǐ qǐng sǎo zhè lǐ","id":"Boleh, silakan scan di sini.","en":"Yes, please scan here."},{"sp":"A","zh":"好了。請問要等多久？","py":"hǎo le qǐng wèn yào děng duō jiǔ","id":"Sudah. Berapa lama menunggunya?","en":"Done. How long is the wait?"},{"sp":"B","zh":"大概五分鐘，做好會叫你的號碼。","py":"dà gài wǔ fēn zhōng zuò hǎo huì jiào nǐ de hào mǎ","id":"Sekitar lima menit, kalau sudah jadi nomormu akan dipanggil.","en":"About five minutes. We'll call your number when it's ready."}],"phrases":[{"zh":"半糖少冰","py":"bàn táng shǎo bīng","id":"setengah gula, es sedikit"},{"zh":"去冰","py":"qù bīng","id":"tanpa es"},{"zh":"無糖","py":"wú táng","id":"tanpa gula"},{"zh":"內用還是外帶","py":"nèi yòng hái shì wài dài","id":"makan di sini atau dibawa pulang?"},{"zh":"可以加料嗎","py":"kě yǐ jiā liào ma","id":"boleh tambah topping?"}],"grammar":["mw","hen","ma"],"task":{"id":"Pesan dua minuman di kedai teh favoritmu: sebutkan ukuran, tingkat manis, es, dan topping, lalu pilih makan di sini atau dibawa pulang."}},{"id":"d_night_market_bargain","dom":"daily","lv":3,"title":{"zh":"夜市殺價","id":"Menawar di pasar malam","en":"Bargaining at the night market"},"goal":{"id":"Setelah ini kamu bisa menanyakan harga, mencoba barang, dan menawar dengan sopan di pasar malam."},"lines":[{"sp":"A","zh":"老闆，這件外套怎麼賣？","py":"lǎo bǎn zhè jiàn wài tào zěn me mài","id":"Pak, jaket ini harganya berapa?","en":"Boss, how much is this jacket?"},{"sp":"B","zh":"一件五百，品質很好喔。","py":"yí jiàn wǔ bǎi pǐn zhí hěn hǎo o","id":"Satu potong 500, kualitasnya bagus lho.","en":"500 each, and the quality is very good."},{"sp":"A","zh":"我可以試穿嗎？","py":"wǒ kě yǐ shì chuān ma","id":"Boleh saya coba?","en":"Can I try it on?"},{"sp":"B","zh":"可以，試衣間在後面。","py":"kě yǐ shì yī jiān zài hòu miàn","id":"Boleh, ruang ganti ada di belakang.","en":"Sure, the fitting room is in the back."},{"sp":"A","zh":"這件剛好。有點貴耶，可以算便宜一點嗎？","py":"zhè jiàn gāng hǎo yǒu diǎn guì ye kě yǐ suàn pián yi yì diǎn ma","id":"Yang ini pas. Agak mahal ya, bisa kurang sedikit?","en":"This one fits. It's a bit expensive. Can you lower the price a little?"},{"sp":"B","zh":"你是學生嗎？那算你四百五。","py":"nǐ shì xué shēng ma nà suàn nǐ sì bǎi wǔ","id":"Kamu pelajar? Kalau begitu 450 untukmu.","en":"Are you a student? Then I'll give you 450."},{"sp":"A","zh":"四百五還是有點貴，我買兩件，一件三百五可以嗎？","py":"sì bǎi wǔ hái shì yǒu diǎn guì wǒ mǎi liǎng jiàn yí jiàn sān bǎi wǔ kě yǐ ma","id":"450 masih agak mahal, saya beli dua, satu 350 boleh?","en":"450 is still a bit much. If I buy two, can it be 350 each?"},{"sp":"B","zh":"哎呀，這樣我賺不到錢啦。兩件七百五好了。","py":"āi yā zhè yàng wǒ zuàn bú dào qián la liǎng jiàn qī bǎi wǔ hǎo le","id":"Aduh, begitu saya tidak untung. Dua potong 750 saja.","en":"Aiya, I won't make any money like that. Let's say 750 for two."},{"sp":"A","zh":"七百就好，我付現金。","py":"qī bǎi jiù hǎo wǒ fù xiàn jīn","id":"700 saja ya, saya bayar tunai.","en":"Just 700, and I'll pay in cash."},{"sp":"B","zh":"好啦好啦，看你是學生，賣你七百。","py":"hǎo la hǎo la kàn nǐ shì xué shēng mài nǐ qī bǎi","id":"Ya sudah, karena kamu pelajar, saya jual 700.","en":"Fine, fine. Since you're a student, I'll sell them for 700."},{"sp":"A","zh":"謝謝老闆！下次我還會來。","py":"xiè xie lǎo bǎn xià cì wǒ hái huì lái","id":"Terima kasih, Pak! Lain kali saya datang lagi.","en":"Thanks, boss! I'll come again next time."}],"phrases":[{"zh":"怎麼賣","py":"zěn me mài","id":"berapa harganya?"},{"zh":"可以算便宜一點嗎","py":"kě yǐ suàn pián yi yì diǎn ma","id":"bisa dikurangi sedikit?"},{"zh":"我買兩件","py":"wǒ mǎi liǎng jiàn","id":"saya beli dua potong"},{"zh":"我付現金","py":"wǒ fù xiàn jīn","id":"saya bayar tunai"},{"zh":"賺不到錢","py":"zuàn bú dào qián","id":"tidak dapat untung"}],"grammar":["mw","hen","ma"],"task":{"id":"Tawar sebuah barang di pasar malam: tanyakan harga, minta diskon, lalu tawarkan beli dua supaya harganya lebih murah."}},{"id":"d_clinic_visit","dom":"daily","lv":4,"title":{"zh":"看診","id":"Berobat ke klinik","en":"Seeing a doctor at a clinic"},"goal":{"id":"Setelah ini kamu bisa mendaftar di klinik, menjelaskan gejala, dan memahami anjuran dokter."},"lines":[{"sp":"A","zh":"你好，我要掛號，我從昨天晚上開始發燒。","py":"nǐ hǎo wǒ yào guà hào wǒ cóng zuó tiān wǎn shàng kāi shǐ fā shāo","id":"Halo, saya mau daftar, saya demam sejak tadi malam.","en":"Hi, I'd like to register. I've had a fever since last night."},{"sp":"B","zh":"請問你有帶健保卡嗎？","py":"qǐng wèn nǐ yǒu dài jiàn bǎo kǎ ma","id":"Apakah kamu membawa kartu asuransi kesehatan?","en":"Did you bring your National Health Insurance card?"},{"sp":"A","zh":"有，在這裡。我是外籍生，有加入健保。","py":"yǒu zài zhè lǐ wǒ shì wài jí shēng yǒu jiā rù jiàn bǎo","id":"Ada, ini. Saya mahasiswa asing dan sudah ikut asuransi kesehatan.","en":"Yes, here it is. I'm an international student and I'm enrolled in the insurance."},{"sp":"B","zh":"好，掛號費一百五十元，請先填這張表，然後等叫號。","py":"hǎo guà hào fèi yì bǎi wǔ shí yuán qǐng xiān tián zhè zhāng biǎo rán hòu děng jiào hào","id":"Baik, biaya pendaftaran 150, tolong isi formulir ini dulu, lalu tunggu dipanggil.","en":"OK, the registration fee is 150. Please fill in this form and wait for your number."},{"sp":"A","zh":"請問大概要等多久？","py":"qǐng wèn dà gài yào děng duō jiǔ","id":"Kira-kira harus menunggu berapa lama?","en":"About how long will I have to wait?"},{"sp":"B","zh":"前面還有五個人，大概二十分鐘。","py":"qián miàn hái yǒu wǔ ge rén dà gài èr shí fēn zhōng","id":"Di depan masih ada lima orang, sekitar dua puluh menit.","en":"There are five people ahead of you, about twenty minutes."},{"sp":"A","zh":"醫生，我喉嚨很痛，還一直咳嗽。","py":"yī shēng wǒ hóu lóng hěn tòng hái yì zhí ké sòu","id":"Dokter, tenggorokan saya sangat sakit dan terus batuk.","en":"Doctor, my throat hurts a lot and I keep coughing."},{"sp":"B","zh":"我看一下。喉嚨有點紅，體溫三十八度，你有沒有對什麼藥過敏？","py":"wǒ kàn yí xià hóu lóng yǒu diǎn hóng tǐ wēn sān shí bā dù nǐ yǒu méi yǒu duì shén me yào guò mǐn","id":"Saya periksa dulu. Tenggorokan agak merah, suhu 38 derajat, kamu alergi obat tertentu?","en":"Let me take a look. Your throat is a bit red and your temperature is 38. Any allergies?"},{"sp":"A","zh":"沒有，我沒有藥物過敏。","py":"méi yǒu wǒ méi yǒu yào wù guò mǐn","id":"Tidak, saya tidak alergi obat.","en":"No, I don't have any drug allergies."},{"sp":"B","zh":"好，我開三天的藥，飯後吃，要多喝水、多休息。","py":"hǎo wǒ kāi sān tiān de yào fàn hòu chī yào duō hē shuǐ duō xiū xí","id":"Baik, saya resepkan obat tiga hari, diminum setelah makan, banyak minum air dan istirahat.","en":"OK, I'll prescribe three days of medicine, to be taken after meals. Drink lots of water and rest."},{"sp":"A","zh":"我需要請假，可以開診斷證明嗎？","py":"wǒ xū yào qǐng jià kě yǐ kāi zhěn duàn zhèng míng ma","id":"Saya perlu izin, bisa dibuatkan surat keterangan dokter?","en":"I need to take sick leave. Could you write me a medical certificate?"},{"sp":"B","zh":"可以，我開給你，記得去櫃檯領藥。","py":"kě yǐ wǒ kāi gěi nǐ jì de qù guì tái lǐng yào","id":"Boleh, saya buatkan, ingat ambil obat di loket.","en":"Yes, I'll write one for you. Remember to pick up your medicine at the counter."},{"sp":"A","zh":"謝謝醫生。","py":"xiè xie yī shēng","id":"Terima kasih, Dokter.","en":"Thank you, doctor."}],"phrases":[{"zh":"掛號","py":"guà hào","id":"mendaftar (ke dokter)"},{"zh":"健保卡","py":"jiàn bǎo kǎ","id":"kartu asuransi kesehatan nasional"},{"zh":"發燒","py":"fā shāo","id":"demam"},{"zh":"藥物過敏","py":"yào wù guò mǐn","id":"alergi obat"},{"zh":"飯後吃","py":"fàn hòu chī","id":"diminum setelah makan"}],"grammar":["ma","le","order"],"task":{"id":"Kamu demam dan batuk. Daftar di klinik, tunjukkan kartu asuransi, jelaskan gejalamu kepada dokter, dan tanyakan surat keterangan sakit."}},{"id":"d_bank_residence_card","dom":"daily","lv":4,"title":{"zh":"銀行開戶","id":"Membuka rekening bank","en":"Opening a bank account"},"goal":{"id":"Setelah ini kamu bisa membuka rekening di bank dengan kartu izin tinggal (居留證) dan bertanya soal biaya."},"lines":[{"sp":"A","zh":"你好，我想開一個帳戶。","py":"nǐ hǎo wǒ xiǎng kāi yí ge zhàng hù","id":"Halo, saya ingin membuka rekening.","en":"Hello, I'd like to open an account."},{"sp":"B","zh":"好的，請問你帶了哪些證件？","py":"hǎo de qǐng wèn nǐ dài le nǎ xiē zhèng jiàn","id":"Baik, dokumen apa saja yang kamu bawa?","en":"Sure, which documents did you bring?"},{"sp":"A","zh":"我帶了護照、居留證和學生證。","py":"wǒ dài le hù zhào jū liú zhèng hé xué shēng zhèng","id":"Saya bawa paspor, kartu izin tinggal, dan kartu mahasiswa.","en":"I brought my passport, residence card, and student ID."},{"sp":"B","zh":"居留證還在有效期限內嗎？","py":"jū liú zhèng hái zài yǒu xiào qí xiàn nèi ma","id":"Apakah kartu izin tinggalmu masih berlaku?","en":"Is your residence card still valid?"},{"sp":"A","zh":"還在，到明年六月。","py":"hái zài dào míng nián liù yuè","id":"Masih, sampai Juni tahun depan.","en":"Yes, until June next year."},{"sp":"B","zh":"好，另外還需要第二證件，像是健保卡。","py":"hǎo lìng wài hái xū yào dì èr zhèng jiàn xiàng shì jiàn bǎo kǎ","id":"Baik, selain itu perlu identitas kedua, misalnya kartu asuransi kesehatan.","en":"OK, we also need a second ID, such as your health insurance card."},{"sp":"A","zh":"我有帶健保卡。可以順便申請提款卡嗎？","py":"wǒ yǒu dài jiàn bǎo kǎ kě yǐ shùn biàn shēn qǐng tí kuǎn kǎ ma","id":"Saya bawa kartu asuransi. Boleh sekalian buat kartu ATM?","en":"I brought my NHI card. Can I apply for an ATM card at the same time?"},{"sp":"B","zh":"可以，請填這份申請書，還要請你設定密碼。","py":"kě yǐ qǐng tián zhè fèn shēn qǐng shū hái yào qǐng nǐ shè dìng mì mǎ","id":"Boleh, tolong isi formulir ini dan atur kata sandi.","en":"Yes, please fill in this application and set a PIN."},{"sp":"A","zh":"我每個月會有打工的薪水轉進來，需要付手續費嗎？","py":"wǒ měi ge yuè huì yǒu dǎ gōng de xīn shuǐ zhuǎn jìn lái xū yào fù shǒu xù fèi ma","id":"Setiap bulan gaji kerja paruh waktu saya akan ditransfer masuk, apakah ada biaya administrasi?","en":"My part-time pay will be transferred in every month. Are there any fees?"},{"sp":"B","zh":"薪轉帳戶不用手續費，不過跨行轉帳每次要十五元。","py":"xīn zhuǎn zhàng hù bú yòng shǒu xù fèi bú guò kuà háng zhuǎn zhàng měi cì yào shí wǔ yuán","id":"Rekening gaji tidak ada biaya, tapi transfer antarbank tiap kali 15 dolar.","en":"Payroll accounts have no fee, but each interbank transfer costs 15."},{"sp":"A","zh":"我懂了。那網路銀行也可以一起申請嗎？","py":"wǒ dǒng le nà wǎng lù yín háng yě kě yǐ yì qǐ shēn qǐng ma","id":"Saya mengerti. Internet banking bisa didaftarkan sekalian?","en":"I see. Can I apply for online banking at the same time?"},{"sp":"B","zh":"可以，大概十分鐘就辦好了，請稍等。","py":"kě yǐ dà gài shí fēn zhōng jiù bàn hǎo le qǐng shāo děng","id":"Bisa, sekitar sepuluh menit sudah selesai, mohon tunggu sebentar.","en":"Yes, it'll be done in about ten minutes. Please wait a moment."}],"phrases":[{"zh":"開一個帳戶","py":"kāi yí ge zhàng hù","id":"membuka rekening"},{"zh":"居留證","py":"jū liú zhèng","id":"kartu izin tinggal"},{"zh":"提款卡","py":"tí kuǎn kǎ","id":"kartu ATM"},{"zh":"手續費","py":"shǒu xù fèi","id":"biaya administrasi"},{"zh":"跨行轉帳","py":"kuà háng zhuǎn zhàng","id":"transfer antarbank"}],"grammar":["ma","mw","le"],"task":{"id":"Kamu datang ke bank untuk membuka rekening. Sebutkan dokumen yang kamu bawa, minta kartu ATM, dan tanyakan biaya transfer."}},{"id":"d_phone_plan","dom":"daily","lv":4,"title":{"zh":"辦手機門號","id":"Membeli paket ponsel","en":"Getting a phone plan"},"goal":{"id":"Setelah ini kamu bisa memilih paket ponsel, menanyakan kontrak, dan menyebut dokumen yang diperlukan."},"lines":[{"sp":"A","zh":"你好，我想辦一個門號，有適合學生的方案嗎？","py":"nǐ hǎo wǒ xiǎng bàn yí ge mén hào yǒu shì hé xué shēng de fāng àn ma","id":"Halo, saya mau membuat nomor baru, ada paket untuk pelajar?","en":"Hello, I'd like to get a new number. Do you have plans for students?"},{"sp":"B","zh":"有，你要月租型還是預付卡？","py":"yǒu nǐ yào yuè zū xíng hái shì yù fù kǎ","id":"Ada, mau paket bulanan atau kartu prabayar?","en":"Yes. Do you want a monthly plan or a prepaid card?"},{"sp":"A","zh":"我在台灣只會待兩年，預付卡會不會比較方便？","py":"wǒ zài tái wān zhǐ huì dāi liǎng nián yù fù kǎ huì bú huì bǐ jiào fāng biàn","id":"Saya hanya tinggal dua tahun di Taiwan, apakah prabayar lebih praktis?","en":"I'll only stay in Taiwan for two years. Would prepaid be more convenient?"},{"sp":"B","zh":"如果你常用網路，月租型比較划算，一個月五百九十九吃到飽。","py":"rú guǒ nǐ cháng yòng wǎng lù yuè zū xíng bǐ jiào huá suàn yí ge yuè wǔ bǎi jiǔ shí jiǔ chī dào bǎo","id":"Kalau sering pakai internet, paket bulanan lebih hemat, 599 per bulan kuota tanpa batas.","en":"If you use data a lot, the monthly plan is better value: 599 a month, unlimited data."},{"sp":"A","zh":"要綁約嗎？","py":"yào bǎng yuē ma","id":"Apakah ada kontrak?","en":"Is there a contract?"},{"sp":"B","zh":"要綁約十二個月，不過有學生優惠，前三個月半價。","py":"yào bǎng yuē shí èr ge yuè bú guò yǒu xué shēng yōu huì qián sān ge yuè bàn jià","id":"Kontrak dua belas bulan, tapi ada diskon pelajar, tiga bulan pertama setengah harga.","en":"A twelve-month contract, but there's a student discount: half price for the first three months."},{"sp":"A","zh":"那通話費怎麼算？我常常打回印尼。","py":"nà tōng huà fèi zěn me suàn wǒ cháng cháng dǎ huí yìn ní","id":"Lalu biaya telepon dihitung bagaimana? Saya sering menelepon ke Indonesia.","en":"How are call charges calculated? I often call Indonesia."},{"sp":"B","zh":"網內互打免費。打回印尼的話，建議你用通訊軟體打，比較省。","py":"wǎng nèi hù dǎ miǎn fèi dǎ huí yìn ní de huà jiàn yì nǐ yòng tōng xùn ruǎn tǐ dǎ bǐ jiào shěng","id":"Telepon sesama operator gratis. Kalau menelepon ke Indonesia, sebaiknya pakai aplikasi chat, lebih hemat.","en":"Calls within the network are free. For calls to Indonesia, I'd suggest a messaging app; it's cheaper."},{"sp":"A","zh":"好，那我辦月租型。需要什麼證件？","py":"hǎo nà wǒ bàn yuè zū xíng xū yào shén me zhèng jiàn","id":"Baik, saya ambil paket bulanan. Perlu dokumen apa?","en":"OK, I'll take the monthly plan. What documents do I need?"},{"sp":"B","zh":"居留證和護照，還有你的銀行帳戶或信用卡，扣款用。","py":"jū liú zhèng hé hù zhào hái yǒu nǐ de yín háng zhàng hù huò xìn yòng kǎ kòu kuǎn yòng","id":"Kartu izin tinggal dan paspor, serta rekening bank atau kartu kredit untuk pemotongan biaya.","en":"Your residence card and passport, plus a bank account or credit card for billing."},{"sp":"A","zh":"都有帶。請問今天可以開通嗎？","py":"dōu yǒu dài qǐng wèn jīn tiān kě yǐ kāi tōng ma","id":"Semua saya bawa. Apakah hari ini bisa langsung aktif?","en":"I have them all. Can it be activated today?"},{"sp":"B","zh":"可以，我現在幫你設定，大概十分鐘就能用了。","py":"kě yǐ wǒ xiàn zài bāng nǐ shè dìng dà gài shí fēn zhōng jiù néng yòng le","id":"Bisa, saya atur sekarang, sekitar sepuluh menit sudah bisa dipakai.","en":"Yes, I'll set it up now and you can use it in about ten minutes."}],"phrases":[{"zh":"辦一個門號","py":"bàn yí ge mén hào","id":"membuat nomor telepon baru"},{"zh":"月租型","py":"yuè zū xíng","id":"paket bulanan"},{"zh":"預付卡","py":"yù fù kǎ","id":"kartu prabayar"},{"zh":"綁約","py":"bǎng yuē","id":"terikat kontrak"},{"zh":"吃到飽","py":"chī dào bǎo","id":"kuota tanpa batas"}],"grammar":["bi","ma","aux"],"task":{"id":"Kamu ingin membeli nomor ponsel. Pilih antara paket bulanan dan prabayar, tanyakan soal kontrak dan dokumen yang perlu dibawa."}},{"id":"d_directions_mrt_bus","dom":"daily","lv":3,"title":{"zh":"問路和搭捷運","id":"Bertanya arah dan naik MRT","en":"Asking directions and taking the MRT"},"goal":{"id":"Setelah ini kamu bisa bertanya arah, memilih jalur MRT atau bus, dan menanyakan cara beli tiket."},"lines":[{"sp":"A","zh":"不好意思，請問高雄車站怎麼走？","py":"bù hǎo yì si qǐng wèn gāo xióng chē zhàn zěn me zǒu","id":"Permisi, bagaimana cara ke Stasiun Kaohsiung?","en":"Excuse me, how do I get to Kaohsiung Station?"},{"sp":"B","zh":"你要搭捷運嗎？前面右轉就是捷運站。","py":"nǐ yào dā jié yùn ma qián miàn yòu zhuǎn jiù shì jié yùn zhàn","id":"Mau naik MRT? Belok kanan di depan, itu stasiun MRT.","en":"Are you taking the MRT? Turn right ahead and you'll see the station."},{"sp":"A","zh":"我從這裡搭哪一條線比較好？","py":"wǒ cóng zhè lǐ dā nǎ yì tiáo xiàn bǐ jiào hǎo","id":"Dari sini sebaiknya naik jalur yang mana?","en":"Which line should I take from here?"},{"sp":"B","zh":"搭紅線往小港方向，坐三站就到高雄車站。","py":"dā hóng xiàn wǎng xiǎo gǎng fāng xiàng zuò sān zhàn jiù dào gāo xióng chē zhàn","id":"Naik jalur merah arah Siaogang, tiga stasiun sudah sampai Stasiun Kaohsiung.","en":"Take the Red Line toward Siaogang. It's three stops to Kaohsiung Station."},{"sp":"A","zh":"要坐多久？票怎麼買？","py":"yào zuò duō jiǔ piào zěn me mǎi","id":"Berapa lama? Tiketnya beli bagaimana?","en":"How long does it take? How do I buy a ticket?"},{"sp":"B","zh":"大概十分鐘。你可以用一卡通，或在售票機買單程票。","py":"dà gài shí fēn zhōng nǐ kě yǐ yòng yì kǎ tōng huò zài shòu piào jī mǎi dān chéng piào","id":"Sekitar sepuluh menit. Bisa pakai kartu iPass atau beli tiket sekali jalan di mesin tiket.","en":"About ten minutes. You can use an iPass card or buy a single-journey ticket at the machine."},{"sp":"A","zh":"那如果我想搭公車呢？","py":"nà rú guǒ wǒ xiǎng dā gōng chē ne","id":"Kalau saya mau naik bus bagaimana?","en":"What if I want to take the bus?"},{"sp":"B","zh":"公車的話，對面站牌有直達車站的車，不過現在下班時間，很容易塞車。","py":"gōng chē de huà duì miàn zhàn pái yǒu zhí dá chē zhàn de chē bú guò xiàn zài xià bān shí jiān hěn róng yì sāi chē","id":"Kalau bus, di halte seberang ada yang langsung ke stasiun, tapi sekarang jam pulang kerja, gampang macet.","en":"As for buses, the stop across the road has one that goes straight to the station, but it's rush hour so there's often traffic."},{"sp":"A","zh":"那我還是搭捷運好了，謝謝你！","py":"nà wǒ hái shì dā jié yùn hǎo le xiè xie nǐ","id":"Kalau begitu saya naik MRT saja, terima kasih!","en":"Then I'll just take the MRT. Thank you!"},{"sp":"B","zh":"不客氣，路上小心。","py":"bú kè qi lù shàng xiǎo xīn","id":"Sama-sama, hati-hati di jalan.","en":"You're welcome. Take care."}],"phrases":[{"zh":"怎麼走","py":"zěn me zǒu","id":"bagaimana cara ke sana"},{"zh":"右轉","py":"yòu zhuǎn","id":"belok kanan"},{"zh":"坐三站","py":"zuò sān zhàn","id":"naik tiga stasiun"},{"zh":"單程票","py":"dān chéng piào","id":"tiket sekali jalan"},{"zh":"塞車","py":"sāi chē","id":"macet"}],"grammar":["congdao","ma","mw"],"task":{"id":"Seorang turis bertanya kepadamu cara ke stasiun kereta terdekat. Jelaskan arah jalan kaki, jalur MRT, dan cara membeli tiket."}},{"id":"d_line_weekend_plans","dom":"daily","lv":3,"title":{"zh":"約週末出去玩","id":"Membuat janji akhir pekan lewat LINE","en":"Making weekend plans on LINE"},"goal":{"id":"Setelah ini kamu bisa mengajak teman, menyepakati hari dan jam, serta tempat bertemu."},"lines":[{"sp":"A","zh":"這個週末你有空嗎？我們要不要一起去西子灣看夕陽？","py":"zhè ge zhōu mò nǐ yǒu kòng ma wǒ men yào bú yào yì qǐ qù xī zǐ wān kàn xī yáng","id":"Akhir pekan ini kamu senggang? Mau pergi melihat matahari terbenam di Sizihwan bersama?","en":"Are you free this weekend? Shall we go watch the sunset at Sizihwan together?"},{"sp":"B","zh":"好啊！星期六還是星期天？","py":"hǎo a xīng qí liù hái shì xīng qí tiān","id":"Boleh! Sabtu atau Minggu?","en":"Sure! Saturday or Sunday?"},{"sp":"A","zh":"星期六下午我要上實驗課，星期天可以。","py":"xīng qí liù xià wǔ wǒ yào shàng shí yàn kè xīng qí tiān kě yǐ","id":"Sabtu sore saya ada praktikum, Minggu bisa.","en":"I have a lab class on Saturday afternoon, but Sunday works."},{"sp":"B","zh":"那就星期天吧，幾點集合？","py":"nà jiù xīng qí tiān ba jǐ diǎn jí hé","id":"Kalau begitu Minggu saja, kumpul jam berapa?","en":"Then let's do Sunday. What time do we meet?"},{"sp":"A","zh":"四點怎麼樣？我們先在捷運站碰面，再騎機車過去。","py":"sì diǎn zěn me yàng wǒ men xiān zài jié yùn zhàn pèng miàn zài qí jī chē guò qù","id":"Jam empat bagaimana? Kita bertemu di stasiun MRT dulu, lalu naik motor ke sana.","en":"How about four o'clock? We meet at the MRT station first, then ride scooters there."},{"sp":"B","zh":"可以，但我的機車在修，可能要請你載我。","py":"kě yǐ dàn wǒ de jī chē zài xiū kě néng yào qǐng nǐ zài wǒ","id":"Boleh, tapi motor saya sedang diperbaiki, mungkin saya minta kamu membonceng saya.","en":"OK, but my scooter is being repaired, so I might need you to give me a ride."},{"sp":"A","zh":"沒問題！我等一下把地點傳給你。","py":"méi wèn tí wǒ děng yí xià bǎ dì diǎn chuán gěi nǐ","id":"Tidak masalah! Nanti lokasinya kukirim ke kamu.","en":"No problem! I'll send you the location in a bit."},{"sp":"B","zh":"收到，我也問一下阿明要不要來。","py":"shōu dào wǒ yě wèn yí xià ā míng yào bú yào lái","id":"Oke, saya juga akan tanya Aming mau ikut atau tidak.","en":"Got it. I'll also ask Aming whether he wants to come."},{"sp":"A","zh":"好啊，人多比較熱鬧。對了，記得帶防曬。","py":"hǎo a rén duō bǐ jiào rè nao duì le jì de dài fáng shài","id":"Boleh, kalau ramai lebih seru. Oh ya, ingat bawa tabir surya.","en":"Sure, more people makes it livelier. Oh, and remember to bring sunscreen."},{"sp":"B","zh":"沒問題，那星期天見！","py":"méi wèn tí nà xīng qí tiān jiàn","id":"Siap, sampai jumpa hari Minggu!","en":"No problem, see you on Sunday!"}],"phrases":[{"zh":"你有空嗎","py":"nǐ yǒu kòng ma","id":"kamu senggang?"},{"zh":"要不要一起去","py":"yào bú yào yì qǐ qù","id":"mau pergi bersama?"},{"zh":"幾點集合","py":"jǐ diǎn jí hé","id":"kumpul jam berapa?"},{"zh":"碰面","py":"pèng miàn","id":"bertemu"},{"zh":"收到","py":"shōu dào","id":"oke, sudah diterima"}],"grammar":["aux","order","ba"],"task":{"id":"Ajak temanmu pergi ke suatu tempat akhir pekan ini lewat LINE. Tentukan hari, jam, tempat bertemu, dan cara pergi."}},{"id":"d_apologize_late","dom":"daily","lv":3,"title":{"zh":"遲到道歉","id":"Minta maaf karena terlambat","en":"Apologizing for being late"},"goal":{"id":"Setelah ini kamu bisa meminta maaf karena terlambat, menjelaskan alasan, dan berjanji memperbaikinya."},"lines":[{"sp":"A","zh":"對不起，我遲到了，你等很久了嗎？","py":"duì bù qǐ wǒ chí dào le nǐ děng hěn jiǔ le ma","id":"Maaf, saya terlambat, kamu sudah menunggu lama?","en":"Sorry, I'm late. Have you been waiting long?"},{"sp":"B","zh":"還好啦，大概等了十分鐘。發生什麼事了？","py":"hái hǎo la dà gài děng le shí fēn zhōng fā shēng shén me shì le","id":"Nggak apa-apa, cuma nunggu sekitar sepuluh menit. Ada apa?","en":"It's fine, I waited about ten minutes. What happened?"},{"sp":"A","zh":"我等的公車一直沒來，後來又遇到大塞車。","py":"wǒ děng de gōng chē yì zhí méi lái hòu lái yòu yù dào dà sāi chē","id":"Bus yang saya tunggu tidak datang-datang, lalu terjebak macet parah.","en":"The bus I was waiting for never came, and then I got stuck in a big traffic jam."},{"sp":"B","zh":"真的嗎？你怎麼不先傳訊息給我？","py":"zhēn de ma nǐ zěn me bù xiān chuán xùn xí gěi wǒ","id":"Benarkah? Kenapa tidak kirim pesan dulu?","en":"Really? Why didn't you message me first?"},{"sp":"A","zh":"我本來想傳，可是手機剛好沒電了，真的很抱歉。","py":"wǒ běn lái xiǎng chuán kě shì shǒu jī gāng hǎo méi diàn le zhēn de hěn bào qiàn","id":"Awalnya mau kirim, tapi ponsel saya kebetulan mati kehabisan baterai, benar-benar minta maaf.","en":"I wanted to, but my phone happened to run out of battery. I'm really sorry."},{"sp":"B","zh":"沒關係，下次如果會遲到，記得先跟我說一聲。","py":"méi guān xi xià cì rú guǒ huì chí dào jì de xiān gēn wǒ shuō yì shēng","id":"Tidak apa-apa, lain kali kalau akan terlambat, ingat beri tahu saya dulu.","en":"No worries. Next time you're going to be late, remember to let me know first."},{"sp":"A","zh":"一定，我下次會提早出門。今天的爆米花我請，當作賠罪。","py":"yí dìng wǒ xià cì huì tí zǎo chū mén jīn tiān de bào mǐ huā wǒ qǐng dāng zuò péi zuì","id":"Pasti, lain kali saya berangkat lebih awal. Popcorn hari ini saya traktir, anggap saja permintaan maaf.","en":"Definitely, next time I'll leave earlier. Popcorn is on me today to make up for it."},{"sp":"B","zh":"哈哈，不用啦。我們快進去吧，電影快開始了。","py":"hā hā bú yòng la wǒ men kuài jìn qù ba diàn yǐng kuài kāi shǐ le","id":"Haha, tidak usah. Ayo cepat masuk, filmnya hampir mulai.","en":"Haha, you don't have to. Let's go in, the movie is about to start."},{"sp":"A","zh":"好，走吧。","py":"hǎo zǒu ba","id":"Ya, ayo.","en":"OK, let's go."}],"phrases":[{"zh":"對不起，我遲到了","py":"duì bù qǐ wǒ chí dào le","id":"maaf, saya terlambat"},{"zh":"真的很抱歉","py":"zhēn de hěn bào qiàn","id":"benar-benar minta maaf"},{"zh":"手機沒電","py":"shǒu jī méi diàn","id":"baterai ponsel habis"},{"zh":"下次記得先說一聲","py":"xià cì jì de xiān shuō yì shēng","id":"lain kali ingat kabari dulu"},{"zh":"我請客","py":"wǒ qǐng kè","id":"saya yang traktir"}],"grammar":["le","aux","ma"],"task":{"id":"Kamu terlambat datang ke janji dengan temanmu. Minta maaf, jelaskan alasannya, dan janjikan sesuatu supaya tidak terulang."}},{"id":"d_parttime_interview","dom":"daily","lv":4,"title":{"zh":"打工面試","id":"Wawancara kerja paruh waktu","en":"Part-time job interview"},"goal":{"id":"Setelah ini kamu bisa memperkenalkan diri, menyebut pengalaman, dan menyampaikan jam kerja yang tersedia."},"lines":[{"sp":"A","zh":"您好，我是來面試服務生的。","py":"nín hǎo wǒ shì lái miàn shì fú wù shēng de","id":"Selamat siang, saya datang untuk wawancara posisi pelayan.","en":"Hello, I'm here for the waiter interview."},{"sp":"B","zh":"你好，請坐。先簡單自我介紹一下吧。","py":"nǐ hǎo qǐng zuò xiān jiǎn dān zì wǒ jiè shào yí xià ba","id":"Halo, silakan duduk. Perkenalkan diri dulu secara singkat.","en":"Hello, please sit. Start with a brief self-introduction."},{"sp":"A","zh":"好的。我是印尼來的留學生，現在讀設備工程系三年級。","py":"hǎo de wǒ shì yìn ní lái de liú xué shēng xiàn zài dú shè bèi gōng chéng xì sān nián jí","id":"Baik. Saya mahasiswa asal Indonesia, sekarang kuliah di jurusan teknik peralatan tahun ketiga.","en":"OK. I'm an international student from Indonesia, currently a third-year in Equipment Engineering."},{"sp":"B","zh":"你的中文說得不錯。你以前有打工經驗嗎？","py":"nǐ de zhōng wén shuō de bú cuò nǐ yǐ qián yǒu dǎ gōng jīng yàn ma","id":"Bahasa Mandarinmu bagus. Apakah kamu punya pengalaman kerja paruh waktu?","en":"Your Chinese is quite good. Do you have any part-time work experience?"},{"sp":"A","zh":"有，我去年在餐廳當過外場，所以會幫客人點餐，也會結帳。","py":"yǒu wǒ qù nián zài cān tīng dāng guò wài chǎng suǒ yǐ huì bāng kè rén diǎn cān yě huì jié zhàng","id":"Ada, tahun lalu saya pernah jadi pelayan di restoran, jadi saya bisa mencatat pesanan tamu dan juga melayani pembayaran.","en":"Yes, last year I worked front-of-house at a restaurant, so I can take orders and handle checkout."},{"sp":"B","zh":"很好。我們需要週末和晚上的人，你什麼時候可以上班？","py":"hěn hǎo wǒ men xū yào zhōu mò hé wǎn shàng de rén nǐ shén me shí hòu kě yǐ shàng bān","id":"Bagus. Kami butuh orang untuk akhir pekan dan malam hari, kapan kamu bisa masuk kerja?","en":"Good. We need people for weekends and evenings. When can you work?"},{"sp":"A","zh":"我星期一到星期四晚上有課，所以週五到週日都可以。","py":"wǒ xīng qí yī dào xīng qí sì wǎn shàng yǒu kè suǒ yǐ zhōu wǔ dào zhōu rì dōu kě yǐ","id":"Senin sampai Kamis malam saya ada kuliah, jadi Jumat sampai Minggu bisa semua.","en":"I have classes Monday to Thursday evenings, so Friday to Sunday are all fine."},{"sp":"B","zh":"另外，你有申請工作許可嗎？","py":"lìng wài nǐ yǒu shēn qǐng gōng zuò xǔ kě ma","id":"Selain itu, kamu sudah mengurus izin kerja?","en":"Also, have you applied for a work permit?"},{"sp":"A","zh":"有，我已經申請了工作許可，每週最多可以工作二十小時。","py":"yǒu wǒ yǐ jīng shēn qǐng le gōng zuò xǔ kě měi zhōu zuì duō kě yǐ gōng zuò èr shí xiǎo shí","id":"Sudah, saya sudah mengurus izin kerja, maksimal dua puluh jam per minggu.","en":"Yes, I already have a work permit. I can work up to twenty hours a week."},{"sp":"B","zh":"時薪是兩百元，月底發薪水，可以嗎？","py":"shí xīn shì liǎng bǎi yuán yuè dǐ fā xīn shuǐ kě yǐ ma","id":"Gaji per jam 200, dibayar akhir bulan, apakah tidak masalah?","en":"The hourly pay is 200, paid at the end of the month. Is that OK?"},{"sp":"A","zh":"可以，謝謝。請問什麼時候可以知道結果？","py":"kě yǐ xiè xie qǐng wèn shén me shí hòu kě yǐ zhī dào jié guǒ","id":"Bisa, terima kasih. Kapan saya bisa tahu hasilnya?","en":"That's fine, thank you. When will I find out the result?"},{"sp":"B","zh":"我們三天內會打電話通知你。","py":"wǒ men sān tiān nèi huì dǎ diàn huà tōng zhī nǐ","id":"Kami akan menelepon kamu dalam tiga hari.","en":"We'll call you within three days."}],"phrases":[{"zh":"自我介紹","py":"zì wǒ jiè shào","id":"perkenalan diri"},{"zh":"打工經驗","py":"dǎ gōng jīng yàn","id":"pengalaman kerja paruh waktu"},{"zh":"什麼時候可以上班","py":"shén me shí hòu kě yǐ shàng bān","id":"kapan bisa mulai kerja"},{"zh":"工作許可","py":"gōng zuò xǔ kě","id":"izin kerja"},{"zh":"時薪","py":"shí xīn","id":"gaji per jam"}],"grammar":["guo","yinwei","aux"],"task":{"id":"Kamu sedang wawancara kerja paruh waktu. Perkenalkan dirimu, sebutkan pengalaman, hari yang bisa kamu kerja, dan izin kerjamu."}},{"id":"d_dinner_split_bill","dom":"daily","lv":4,"title":{"zh":"聚餐和分帳","id":"Makan bersama dan patungan","en":"Dinner with friends and splitting the bill"},"goal":{"id":"Setelah ini kamu bisa mengajak teman makan bersama, memesan tempat, dan membagi tagihan."},"lines":[{"sp":"A","zh":"期中考結束了，今天晚上要不要一起吃火鍋慶祝？","py":"qí zhōng kǎo jié shù le jīn tiān wǎn shàng yào bú yào yì qǐ chī huǒ guō qìng zhù","id":"Ujian tengah semester sudah selesai, malam ini mau makan hot pot bersama untuk merayakan?","en":"Midterms are over. Want to have hot pot tonight to celebrate?"},{"sp":"B","zh":"好啊！我已經好久沒吃火鍋了。你有訂位嗎？","py":"hǎo a wǒ yǐ jīng hǎo jiǔ méi chī huǒ guō le nǐ yǒu dìng wèi ma","id":"Boleh! Sudah lama sekali saya tidak makan hot pot. Sudah reservasi?","en":"Sure! I haven't had hot pot in ages. Have you booked a table?"},{"sp":"A","zh":"還沒，我現在打電話訂，六個人七點可以嗎？","py":"hái méi wǒ xiàn zài dǎ diàn huà dìng liù ge rén qī diǎn kě yǐ ma","id":"Belum, saya telepon sekarang, enam orang jam tujuh bisa?","en":"Not yet. I'll call now. Is seven o'clock OK for six people?"},{"sp":"B","zh":"可以。對了，阿里不吃豬肉，點肉的時候要注意一下。","py":"kě yǐ duì le ā lǐ bù chī zhū ròu diǎn ròu de shí hòu yào zhù yì yí xià","id":"Bisa. Oh ya, Ali tidak makan babi, waktu pesan daging harus hati-hati.","en":"OK. Oh, Ali doesn't eat pork, so we need to be careful when ordering meat."},{"sp":"A","zh":"沒問題，我會先跟店員說一聲。那晚上七點見！","py":"méi wèn tí wǒ huì xiān gēn diàn yuán shuō yì shēng nà wǎn shàng qī diǎn jiàn","id":"Tidak masalah, saya akan bilang ke pelayan dulu. Sampai jumpa jam tujuh malam!","en":"No problem, I'll tell the staff first. See you at seven!"},{"sp":"B","zh":"好，晚上見！","py":"hǎo wǎn shàng jiàn","id":"Oke, sampai malam nanti!","en":"OK, see you tonight!"},{"sp":"A","zh":"好飽喔！我去櫃檯結帳，等一下再算給你們。","py":"hǎo bǎo o wǒ qù guì tái jié zhàng děng yí xià zài suàn gěi nǐ men","id":"Kenyang sekali! Saya bayar di kasir dulu, nanti saya hitung ke kalian.","en":"I'm so full! I'll go pay at the counter and work out what you owe later."},{"sp":"B","zh":"好，總共多少？我轉帳給你。","py":"hǎo zǒng gòng duō shǎo wǒ zhuǎn zhàng gěi nǐ","id":"Oke, totalnya berapa? Saya transfer ke kamu.","en":"OK, how much in total? I'll transfer it to you."},{"sp":"A","zh":"三千六百元，六個人平分，一個人六百。","py":"sān qiān liù bǎi yuán liù ge rén píng fēn yí ge rén liù bǎi","id":"3.600, dibagi rata untuk enam orang, satu orang 600.","en":"3,600 in total, split evenly among six people, so 600 each."},{"sp":"B","zh":"好，我現在轉給你。對了，下次換我請客。","py":"hǎo wǒ xiàn zài zhuǎn gěi nǐ duì le xià cì huàn wǒ qǐng kè","id":"Oke, saya transfer sekarang. Oh ya, lain kali gantian saya yang traktir.","en":"OK, I'll transfer it now. And next time it's my treat."},{"sp":"A","zh":"一言為定！那下個月我們去吃燒肉。","py":"yì yán wéi dìng nà xià ge yuè wǒ men qù chī shāo ròu","id":"Sepakat! Kalau begitu bulan depan kita makan yakiniku.","en":"Deal! Then next month we'll go for yakiniku."}],"phrases":[{"zh":"要不要一起吃飯","py":"yào bú yào yì qǐ chī fàn","id":"mau makan bersama?"},{"zh":"訂位","py":"dìng wèi","id":"reservasi tempat"},{"zh":"結帳","py":"jié zhàng","id":"membayar tagihan"},{"zh":"平分","py":"píng fēn","id":"dibagi rata"},{"zh":"下次換我請客","py":"xià cì huàn wǒ qǐng kè","id":"lain kali gantian saya traktir"}],"grammar":["aux","order","le"],"task":{"id":"Ajak teman-temanmu makan malam, lalu setelah makan hitung total tagihan dan bagi rata. Janjikan juga giliran traktir berikutnya."}},{"id":"d_weekend_hobbies","dom":"daily","lv":3,"title":{"zh":"聊週末和興趣","id":"Mengobrol soal akhir pekan dan hobi","en":"Talking about weekends and hobbies"},"goal":{"id":"Setelah ini kamu bisa menceritakan kegiatan akhir pekan dan hobimu serta bertanya balik kepada teman."},"lines":[{"sp":"A","zh":"你週末都做什麼？","py":"nǐ zhōu mò dōu zuò shén me","id":"Kamu biasanya ngapain di akhir pekan?","en":"What do you usually do on weekends?"},{"sp":"B","zh":"我常常去愛河騎腳踏車，有時候也去健身房。你呢？","py":"wǒ cháng cháng qù ài hé qí jiǎo tà chē yǒu shí hòu yě qù jiàn shēn fáng nǐ ne","id":"Saya sering bersepeda di Sungai Cinta, kadang juga ke gym. Kamu?","en":"I often cycle along the Love River, and sometimes I go to the gym. You?"},{"sp":"A","zh":"我喜歡打籃球，不過最近天氣太熱，所以改成在家打電動。","py":"wǒ xǐ huān dǎ lán qiú bú guò zuì jìn tiān qì tài rè suǒ yǐ gǎi chéng zài jiā dǎ diàn dòng","id":"Saya suka main basket, tapi akhir-akhir ini cuaca terlalu panas, jadi diganti main game di rumah.","en":"I like playing basketball, but it's been too hot lately, so I switched to playing video games at home."},{"sp":"B","zh":"你都玩什麼遊戲？","py":"nǐ dōu wán shén me yóu xì","id":"Kamu main game apa saja?","en":"What games do you play?"},{"sp":"A","zh":"主要是手機遊戲，有時候也跟印尼的朋友線上一起玩。","py":"zhǔ yào shì shǒu jī yóu xì yǒu shí hòu yě gēn yìn ní de péng yǒu xiàn shàng yì qǐ wán","id":"Terutama game ponsel, kadang juga main online bersama teman dari Indonesia.","en":"Mostly mobile games, and sometimes I play online with friends from Indonesia."},{"sp":"B","zh":"真好！我最近在學做菜，上個週末煮了咖哩雞。","py":"zhēn hǎo wǒ zuì jìn zài xué zuò cài shàng ge zhōu mò zhǔ le gā lí jī","id":"Asyik! Saya belakangan ini belajar masak, akhir pekan lalu saya masak ayam kari.","en":"Nice! I've been learning to cook lately. Last weekend I made chicken curry."},{"sp":"A","zh":"哇，你會做菜？我只會煮泡麵。","py":"wā nǐ huì zuò cài wǒ zhǐ huì zhǔ pào miàn","id":"Wah, kamu bisa masak? Saya cuma bisa masak mi instan.","en":"Wow, you can cook? I can only make instant noodles."},{"sp":"B","zh":"其實不難，下次我教你。你要不要一起來？","py":"qí shí bù nán xià cì wǒ jiāo nǐ nǐ yào bú yào yì qǐ lái","id":"Sebenarnya tidak sulit, lain kali saya ajari. Mau ikut?","en":"It's actually not hard. I'll teach you next time. Want to join?"},{"sp":"A","zh":"好啊！我再帶一些印尼的香料來。","py":"hǎo a wǒ zài dài yì xiē yìn ní de xiāng liào lái","id":"Mau! Saya akan bawa juga beberapa bumbu dari Indonesia.","en":"Sure! I'll bring some Indonesian spices too."},{"sp":"B","zh":"太棒了，那我們這個週末就開始吧。","py":"tài bàng le nà wǒ men zhè ge zhōu mò jiù kāi shǐ ba","id":"Hebat, kalau begitu kita mulai akhir pekan ini.","en":"Awesome, then let's start this weekend."}],"phrases":[{"zh":"你週末都做什麼","py":"nǐ zhōu mò dōu zuò shén me","id":"kamu biasanya ngapain di akhir pekan"},{"zh":"有時候","py":"yǒu shí hòu","id":"kadang-kadang"},{"zh":"最近在學","py":"zuì jìn zài xué","id":"belakangan ini sedang belajar"},{"zh":"其實不難","py":"qí shí bù nán","id":"sebenarnya tidak sulit"},{"zh":"下次我教你","py":"xià cì wǒ jiāo nǐ","id":"lain kali saya ajari kamu"}],"grammar":["zai","le","aux"],"task":{"id":"Ceritakan kepada temanmu apa yang biasa kamu lakukan di akhir pekan, hobimu, dan sesuatu baru yang sedang kamu pelajari."}},{"id":"d_delivery_problem","dom":"daily","lv":4,"title":{"zh":"包裹問題","id":"Masalah pengiriman paket","en":"Handling a delivery problem"},"goal":{"id":"Setelah ini kamu bisa melaporkan paket yang tidak diterima dan meminta solusi kepada layanan pelanggan."},"lines":[{"sp":"A","zh":"喂，你好，我昨天訂的包裹顯示已經送達，可是我沒有收到。","py":"wèi nǐ hǎo wǒ zuó tiān dìng de bāo guǒ xiǎn shì yǐ jīng sòng dá kě shì wǒ méi yǒu shōu dào","id":"Halo, paket yang saya pesan kemarin tertulis sudah sampai, tapi saya belum menerimanya.","en":"Hello, the parcel I ordered yesterday shows as delivered, but I haven't received it."},{"sp":"B","zh":"不好意思，請問您的訂單編號是多少？","py":"bù hǎo yì si qǐng wèn nín de dìng dān biān hào shì duō shǎo","id":"Mohon maaf, boleh tahu nomor pesanan Anda?","en":"I'm sorry about that. What's your order number?"},{"sp":"A","zh":"編號是八七六五四三。","py":"biān hào shì bā qī liù wǔ sì sān","id":"Nomornya delapan tujuh enam lima empat tiga.","en":"The number is 876543."},{"sp":"B","zh":"我查一下，系統顯示今天下午兩點已經放在你們大樓的管理室了。","py":"wǒ chá yí xià xì tǒng xiǎn shì jīn tiān xià wǔ liǎng diǎn yǐ jīng fàng zài nǐ men dà lóu de guǎn lǐ shì le","id":"Saya cek dulu, sistem menunjukkan hari ini jam dua siang sudah diletakkan di ruang pengelola gedung kalian.","en":"Let me check. The system shows it was left at your building's management office at 2 p.m. today."},{"sp":"A","zh":"可是我剛剛問過管理員，他說沒有收到我的包裹。","py":"kě shì wǒ gāng gāng wèn guò guǎn lǐ yuán tā shuō méi yǒu shōu dào wǒ de bāo guǒ","id":"Tapi tadi saya sudah tanya petugas, katanya tidak menerima paket saya.","en":"But I just asked the caretaker and he said he never received my parcel."},{"sp":"B","zh":"這樣的話，我請送貨的司機再確認一下，大概一個小時內回電給你，可以嗎？","py":"zhè yàng de huà wǒ qǐng sòng huò de sī jī zài què rèn yí xià dà gài yí ge xiǎo shí nèi huí diàn gěi nǐ kě yǐ ma","id":"Kalau begitu, saya minta kurir memastikan lagi, kira-kira dalam satu jam saya telepon balik, boleh?","en":"In that case, I'll ask the driver to double-check and call you back within about an hour. Is that OK?"},{"sp":"A","zh":"可以，不過那個包裹裡面有我明天要考試用的計算機，很急。","py":"kě yǐ bú guò nà ge bāo guǒ lǐ miàn yǒu wǒ míng tiān yào kǎo shì yòng de jì suàn jī hěn jí","id":"Boleh, tapi di dalam paket itu ada kalkulator untuk ujian saya besok, sangat mendesak.","en":"Yes, but that parcel contains the calculator I need for my exam tomorrow. It's urgent."},{"sp":"B","zh":"我了解，我會優先處理。如果找不到，我們可以重新寄一個，或是全額退款。","py":"wǒ liǎo jiě wǒ huì yōu xiān chǔ lǐ rú guǒ zhǎo bú dào wǒ men kě yǐ chóng xīn jì yí ge huò shì quán é tuì kuǎn","id":"Saya mengerti, akan saya prioritaskan. Kalau tidak ketemu, kami bisa kirim ulang atau mengembalikan dana penuh.","en":"I understand and I'll prioritize it. If it can't be found, we can resend one or give a full refund."},{"sp":"A","zh":"好，麻煩你儘快處理，謝謝。","py":"hǎo má fán nǐ jǐn kuài chǔ lǐ xiè xie","id":"Baik, mohon segera ditangani, terima kasih.","en":"OK, please handle it as soon as possible. Thank you."},{"sp":"B","zh":"不會，不好意思造成你的困擾。","py":"bú huì bù hǎo yì si zào chéng nǐ de kùn rǎo","id":"Sama-sama, mohon maaf atas ketidaknyamanannya.","en":"Not at all, and I apologize for the trouble."}],"phrases":[{"zh":"顯示已經送達","py":"xiǎn shì yǐ jīng sòng dá","id":"tertulis sudah terkirim"},{"zh":"沒有收到","py":"méi yǒu shōu dào","id":"belum menerima"},{"zh":"訂單編號","py":"dìng dān biān hào","id":"nomor pesanan"},{"zh":"重新寄","py":"chóng xīn jì","id":"kirim ulang"},{"zh":"全額退款","py":"quán é tuì kuǎn","id":"pengembalian dana penuh"}],"grammar":["guo","ma","le"],"task":{"id":"Paketmu tertulis sudah sampai tapi belum kamu terima. Telepon layanan pelanggan, sebutkan nomor pesanan, dan minta solusi."}},{"id":"c_ask_prof_after_class","dom":"campus","lv":3,"title":{"zh":"下課後問老師問題","id":"Bertanya kepada dosen setelah kelas","en":"Asking the professor after class"},"goal":{"id":"Setelah ini kamu bisa sopan bertanya kepada dosen setelah kelas dan meminta materi kuliah."},"lines":[{"sp":"A","zh":"老師，不好意思，可以問您一個問題嗎？","py":"lǎo shī bù hǎo yì si kě yǐ wèn nín yí ge wèn tí ma","id":"Pak/Bu, maaf, boleh saya bertanya satu hal?","en":"Professor, excuse me, may I ask you a question?"},{"sp":"B","zh":"當然可以，你說。","py":"dāng rán kě yǐ nǐ shuō","id":"Tentu boleh, silakan.","en":"Of course, go ahead."},{"sp":"A","zh":"剛剛講的薄膜沉積，我不太懂為什麼要抽真空。","py":"gāng gāng jiǎng de bó mó chén jī wǒ bú tài dǒng wèi shén me yào chōu zhēn kōng","id":"Soal pengendapan lapisan tipis yang tadi dijelaskan, saya kurang paham kenapa harus divakum.","en":"About the thin film deposition you just explained, I don't quite get why we need to pump down to a vacuum."},{"sp":"B","zh":"因為空氣裡有很多雜質，會影響薄膜的品質。","py":"yīn wèi kōng qì lǐ yǒu hěn duō zá zhí huì yǐng xiǎng bó mó de pǐn zhí","id":"Karena di udara banyak pengotor yang memengaruhi kualitas lapisan tipis.","en":"Because the air has lots of impurities that affect the film quality."},{"sp":"A","zh":"原來是這樣。那壓力越低越好嗎？","py":"yuán lái shì zhè yàng nà yā lì yuè dī yuè hǎo ma","id":"Oh begitu. Jadi semakin rendah tekanannya semakin bagus?","en":"I see. So the lower the pressure, the better?"},{"sp":"B","zh":"不一定，要看製程需求，太低的話成本會很高。","py":"bù yí dìng yào kàn zhì chéng xū qiú tài dī de huà chéng běn huì hěn gāo","id":"Belum tentu, tergantung kebutuhan proses; kalau terlalu rendah biayanya sangat tinggi.","en":"Not necessarily. It depends on the process requirements, and if it's too low the cost gets very high."},{"sp":"A","zh":"我懂了。可以把投影片傳給我嗎？我想回去再看一次。","py":"wǒ dǒng le kě yǐ bǎ tóu yǐng piàn chuán gěi wǒ ma wǒ xiǎng huí qù zài kàn yí cì","id":"Saya mengerti. Boleh kirim slidenya ke saya? Saya mau lihat lagi di rumah.","en":"I get it now. Could you send me the slides? I'd like to look at them again at home."},{"sp":"B","zh":"好，我今天晚上會上傳到教學平台。","py":"hǎo wǒ jīn tiān wǎn shàng huì shàng chuán dào jiào xué píng tái","id":"Baik, malam ini saya unggah ke platform e-learning.","en":"OK, I'll upload them to the course platform tonight."},{"sp":"A","zh":"謝謝老師，不好意思佔用您的時間。","py":"xiè xie lǎo shī bù hǎo yì si zhàn yòng nín de shí jiān","id":"Terima kasih, maaf sudah menyita waktu Bapak/Ibu.","en":"Thank you, Professor. Sorry for taking your time."},{"sp":"B","zh":"沒關係，有問題隨時來問我。","py":"méi guān xi yǒu wèn tí suí shí lái wèn wǒ","id":"Tidak apa-apa, kalau ada pertanyaan datang saja kapan pun.","en":"No problem, come ask me any time you have questions."}],"phrases":[{"zh":"不好意思，可以問您一個問題嗎？","py":"bù hǎo yì si kě yǐ wèn nín yí ge wèn tí ma","id":"Maaf, boleh saya bertanya?"},{"zh":"我不太懂為什麼……","py":"wǒ bú tài dǒng wèi shén me","id":"Saya kurang paham kenapa ..."},{"zh":"可以把投影片傳給我嗎？","py":"kě yǐ bǎ tóu yǐng piàn chuán gěi wǒ ma","id":"Boleh kirim slidenya ke saya?"},{"zh":"不好意思佔用您的時間","py":"bù hǎo yì si zhàn yòng nín de shí jiān","id":"maaf menyita waktu Anda"},{"zh":"有問題隨時來問我","py":"yǒu wèn tí suí shí lái wèn wǒ","id":"kalau ada pertanyaan tanya saja kapan pun"}],"grammar":["ba","yinwei","yuelai"],"task":{"id":"Tanyakan satu pertanyaan tentang materi kuliah kepada dosen dan minta slide-nya dengan sopan."}},{"id":"c_ask_leave_message","dom":"campus","lv":3,"title":{"zh":"傳訊息請假","id":"Izin tidak masuk lewat pesan","en":"Asking for leave by message"},"goal":{"id":"Setelah ini kamu bisa mengirim pesan izin sakit kepada dosen dan menanyakan tugas yang tertinggal."},"lines":[{"sp":"A","zh":"老師您好，我是設備系三年級的林大明。","py":"lǎo shī nín hǎo wǒ shì shè bèi xì sān nián jí de lín dà míng","id":"Selamat pagi Pak/Bu, saya Wang Enyu dari jurusan peralatan tingkat tiga.","en":"Hello Professor, this is Wang En-Yu from third-year Equipment Engineering."},{"sp":"B","zh":"你好，有什麼事嗎？","py":"nǐ hǎo yǒu shén me shì ma","id":"Halo, ada apa?","en":"Hello, what is it?"},{"sp":"A","zh":"我今天早上發燒了，想跟您請假。","py":"wǒ jīn tiān zǎo shàng fā shāo le xiǎng gēn nín qǐng jià","id":"Pagi ini saya demam, mau izin tidak masuk.","en":"I came down with a fever this morning and would like to ask for leave."},{"sp":"B","zh":"要不要緊？有去看醫生嗎？","py":"yào bú yào jǐn yǒu qù kàn yī shēng ma","id":"Parah tidak? Sudah ke dokter?","en":"Is it serious? Have you seen a doctor?"},{"sp":"A","zh":"我等一下就去診所。今天下午的實習課可能沒辦法去。","py":"wǒ děng yí xià jiù qù zhěn suǒ jīn tiān xià wǔ de shí xí kè kě néng méi bàn fǎ qù","id":"Sebentar lagi saya ke klinik. Kelas praktik sore ini mungkin tidak bisa hadir.","en":"I'm going to the clinic in a bit. I probably can't make this afternoon's lab class."},{"sp":"B","zh":"好，先休息吧。請假單記得補交，也要附醫生的證明。","py":"hǎo xiān xiū xí ba qǐng jià dān jì de bǔ jiāo yě yào fù yī shēng de zhèng míng","id":"Baik, istirahat dulu. Ingat susulkan formulir izin dan lampirkan surat dokter.","en":"OK, rest first. Remember to hand in the leave form later, with a doctor's note attached."},{"sp":"A","zh":"好的，我會在三天內補交。那今天的實驗報告怎麼辦？","py":"hǎo de wǒ huì zài sān tiān nèi bǔ jiāo nà jīn tiān de shí yàn bào gào zěn me bàn","id":"Baik, saya susulkan dalam tiga hari. Lalu laporan praktikum hari ini bagaimana?","en":"Okay, I'll hand it in within three days. What about today's lab report?"},{"sp":"B","zh":"你跟同組的同學拿實驗數據，下禮拜再交就可以了。","py":"nǐ gēn tóng zǔ de tóng xué ná shí yàn shù jù xià lǐ bài zài jiāo jiù kě yǐ le","id":"Minta data praktikum dari teman sekelompokmu, kumpulkan minggu depan saja.","en":"Get the lab data from your group mates and hand it in next week."},{"sp":"A","zh":"謝謝老師，我會注意身體，抱歉造成您的困擾。","py":"xiè xie lǎo shī wǒ huì zhù yì shēn tǐ bào qiàn zào chéng nín de kùn rǎo","id":"Terima kasih, saya akan jaga kesehatan, maaf merepotkan.","en":"Thank you, I'll take care of myself. Sorry for the trouble."},{"sp":"B","zh":"不會，好好休息，早日康復。","py":"bú huì hǎo hǎo xiū xí zǎo rì kāng fù","id":"Tidak apa-apa, istirahat yang cukup, semoga cepat sembuh.","en":"No problem. Get some rest and get well soon."}],"phrases":[{"zh":"想跟您請假","py":"xiǎng gēn nín qǐng jià","id":"ingin izin kepada Anda"},{"zh":"我今天早上發燒了","py":"wǒ jīn tiān zǎo shàng fā shāo le","id":"pagi ini saya demam"},{"zh":"請假單記得補交","py":"qǐng jià dān jì de bǔ jiāo","id":"ingat susulkan formulir izin"},{"zh":"抱歉造成您的困擾","py":"bào qiàn zào chéng nín de kùn rǎo","id":"maaf merepotkan Anda"},{"zh":"早日康復","py":"zǎo rì kāng fù","id":"semoga cepat sembuh"}],"grammar":["le","aux","order"],"task":{"id":"Tulis pesan singkat kepada dosen untuk izin karena sakit dan tanyakan cara menyusul tugas."}},{"id":"c_group_project_division","dom":"campus","lv":4,"title":{"zh":"期末專題分工","id":"Pembagian tugas proyek kelompok","en":"Dividing up the group project"},"goal":{"id":"Setelah ini kamu bisa membagi tugas proyek kelompok dan menyepakati tenggat waktu."},"lines":[{"sp":"A","zh":"這次的期末專題，我們先來分工吧。","py":"zhè cì de qí mò zhuān tí wǒ men xiān lái fēn gōng ba","id":"Untuk proyek akhir kali ini, ayo kita bagi tugas dulu.","en":"For this final project, let's divide up the work first."},{"sp":"B","zh":"好啊。我程式比較強，程式的部分我來負責。","py":"hǎo a wǒ chéng shì bǐ jiào qiáng chéng shì de bù fèn wǒ lái fù zé","id":"Boleh. Saya lebih kuat di pemrograman, bagian program saya yang tangani.","en":"Sure. I'm better at coding, so I'll take care of the programming part."},{"sp":"A","zh":"那我負責寫報告和做簡報，可以嗎？","py":"nà wǒ fù zé xiě bào gào hé zuò jiǎn bào kě yǐ ma","id":"Kalau begitu saya tulis laporan dan buat presentasi, boleh?","en":"Then I'll write the report and make the slides. Is that okay?"},{"sp":"B","zh":"可以，不過感測器的校正會花不少時間，要不要找小陳一起？","py":"kě yǐ bú guò gǎn cè qì de jiào zhèng huì huā bù shǎo shí jiān yào bú yào zhǎo xiǎo chén yì qǐ","id":"Boleh, tapi kalibrasi sensor makan waktu lumayan, bagaimana kalau ajak Xiao Chen?","en":"Okay, but calibrating the sensor takes quite some time. Should we ask Xiao Chen to join?"},{"sp":"A","zh":"好，那就讓他負責測試和記錄數據。","py":"hǎo nà jiù ràng tā fù zé cè shì hé jì lù shù jù","id":"Baik, biar dia yang menguji dan mencatat data.","en":"Good, then he'll handle testing and recording the data."},{"sp":"B","zh":"我們什麼時候要完成第一版？","py":"wǒ men shén me shí hòu yào wán chéng dì yī bǎn","id":"Kapan kita harus menyelesaikan versi pertama?","en":"When do we need to finish the first version?"},{"sp":"A","zh":"我覺得下禮拜五以前要把電路接好，不然來不及。","py":"wǒ jué de xià lǐ bài wǔ yǐ qián yào bǎ diàn lù jiē hǎo bù rán lái bù jí","id":"Menurut saya sebelum Jumat depan rangkaiannya harus sudah terpasang, kalau tidak tidak keburu.","en":"I think the circuit has to be wired up before next Friday, or we won't make it."},{"sp":"B","zh":"沒問題。我們開一個群組，進度隨時更新。","py":"méi wèn tí wǒ men kāi yí ge qún zǔ jìn dù suí shí gēng xīn","id":"Oke. Kita buat satu grup chat, kemajuan diperbarui kapan saja.","en":"No problem. Let's start a group chat and update our progress any time."},{"sp":"A","zh":"好，我等一下就建好，再把你們加進去。","py":"hǎo wǒ děng yí xià jiù jiàn hǎo zài bǎ nǐ men jiā jìn qù","id":"Baik, sebentar lagi saya buat lalu saya masukkan kalian.","en":"Okay, I'll set it up in a moment and add you all."}],"phrases":[{"zh":"我們先來分工吧","py":"wǒ men xiān lái fēn gōng ba","id":"ayo kita bagi tugas dulu"},{"zh":"這部分我來負責","py":"zhè bù fèn wǒ lái fù zé","id":"bagian ini saya yang tangani"},{"zh":"要不要找他一起？","py":"yào bú yào zhǎo tā yì qǐ","id":"bagaimana kalau ajak dia?"},{"zh":"不然來不及","py":"bù rán lái bù jí","id":"kalau tidak, tidak keburu"},{"zh":"進度隨時更新","py":"jìn dù suí shí gēng xīn","id":"kemajuan diperbarui kapan saja"}],"grammar":["ba","order","qw"],"task":{"id":"Bagi tiga bagian tugas proyek kelompokmu dan sebutkan siapa yang bertanggung jawab serta tenggatnya."}},{"id":"c_prepare_presentation","dom":"campus","lv":4,"title":{"zh":"準備簡報","id":"Menyiapkan presentasi","en":"Preparing a presentation"},"goal":{"id":"Setelah ini kamu bisa mendiskusikan perbaikan slide dan latihan presentasi dengan teman."},"lines":[{"sp":"A","zh":"明天就要上台報告了，簡報你準備好了嗎？","py":"míng tiān jiù yào shàng tái bào gào le jiǎn bào nǐ zhǔn bèi hǎo le ma","id":"Besok sudah harus presentasi, slide-mu sudah siap?","en":"We present tomorrow. Is your slide deck ready?"},{"sp":"B","zh":"大概好了，但是我覺得字太多了。","py":"dà gài hǎo le dàn shì wǒ jué de zì tài duō le","id":"Kira-kira sudah, tapi menurutku tulisannya terlalu banyak.","en":"Mostly, but I think there's too much text."},{"sp":"A","zh":"對，一頁最好不要超過五行，多放一些圖。","py":"duì yí yè zuì hǎo bú yào chāo guò wǔ háng duō fàng yì xiē tú","id":"Betul, satu halaman sebaiknya tidak lebih dari lima baris, tambahkan lebih banyak gambar.","en":"Right. Keep each page to five lines at most and add more pictures."},{"sp":"B","zh":"有道理。那數據的部分用圖表會比較清楚。","py":"yǒu dào lǐ nà shù jù de bù fèn yòng tú biǎo huì bǐ jiào qīng chǔ","id":"Masuk akal. Bagian data lebih jelas kalau pakai grafik.","en":"Makes sense. The data part will be clearer as a chart."},{"sp":"A","zh":"還有，你講的時候不要一直看稿子，要看台下的人。","py":"hái yǒu nǐ jiǎng de shí hòu bú yào yì zhí kàn gǎo zi yào kàn tái xià de rén","id":"Lalu, saat bicara jangan terus melihat naskah, lihatlah audiens.","en":"Also, don't keep staring at your script while speaking. Look at the audience."},{"sp":"B","zh":"我有點緊張，怕講到一半忘記。","py":"wǒ yǒu diǎn jǐn zhāng pà jiǎng dào yí bàn wàng jì","id":"Aku agak gugup, takut lupa di tengah-tengah.","en":"I'm a bit nervous and afraid I'll forget halfway through."},{"sp":"A","zh":"我們現在先練習一次，我幫你計時。","py":"wǒ men xiàn zài xiān liàn xí yí cì wǒ bāng nǐ jì shí","id":"Ayo latihan sekali sekarang, aku bantu hitung waktunya.","en":"Let's practice once now, and I'll time you."},{"sp":"B","zh":"好，老師規定每組只有十分鐘。","py":"hǎo lǎo shī guī dìng měi zǔ zhǐ yǒu shí fēn zhōng","id":"Oke, dosen menetapkan tiap kelompok hanya sepuluh menit.","en":"Okay, the teacher set only ten minutes per group."},{"sp":"A","zh":"那就控制在九分鐘，留一點時間回答問題。","py":"nà jiù kòng zhì zài jiǔ fēn zhōng liú yì diǎn shí jiān huí dá wèn tí","id":"Kalau begitu batasi sembilan menit, sisakan sedikit waktu untuk menjawab pertanyaan.","en":"Then keep it to nine minutes and leave a little time for questions."}],"phrases":[{"zh":"上台報告","py":"shàng tái bào gào","id":"presentasi di depan"},{"zh":"字太多了","py":"zì tài duō le","id":"tulisannya terlalu banyak"},{"zh":"一頁最好不要超過五行","py":"yí yè zuì hǎo bú yào chāo guò wǔ háng","id":"satu halaman sebaiknya tidak lebih dari lima baris"},{"zh":"我幫你計時","py":"wǒ bāng nǐ jì shí","id":"aku bantu hitung waktunya"},{"zh":"留一點時間回答問題","py":"liú yì diǎn shí jiān huí dá wèn tí","id":"sisakan sedikit waktu untuk menjawab pertanyaan"}],"grammar":["le","aux","degree"],"task":{"id":"Beri dua saran untuk memperbaiki slide temanmu dan sebutkan berapa lama kalian akan berlatih."}},{"id":"c_lab_safety_briefing","dom":"campus","lv":4,"title":{"zh":"實驗室安全說明","id":"Pengarahan keselamatan laboratorium","en":"Lab safety briefing"},"goal":{"id":"Setelah ini kamu bisa memahami aturan keselamatan lab dan menanyakan hal yang belum jelas."},"lines":[{"sp":"A","zh":"進實驗室之前，先聽我說明安全規定。","py":"jìn shí yàn shì zhī qián xiān tīng wǒ shuō míng ān quán guī dìng","id":"Sebelum masuk lab, dengarkan dulu penjelasan aturan keselamatan.","en":"Before going into the lab, listen to the safety rules first."},{"sp":"B","zh":"好的，老師。","py":"hǎo de lǎo shī","id":"Baik, Pak/Bu.","en":"Yes, Professor."},{"sp":"A","zh":"第一，一定要穿實驗衣，也要戴護目鏡。","py":"dì yī yí dìng yào chuān shí yàn yī yě yào dài hù mù jìng","id":"Pertama, wajib memakai jas lab dan kacamata pelindung.","en":"First, you must wear a lab coat and safety goggles."},{"sp":"B","zh":"頭髮和鞋子有什麼規定嗎？","py":"tóu fǎ hé xié zi yǒu shén me guī dìng ma","id":"Apakah ada aturan untuk rambut dan sepatu?","en":"Are there any rules about hair and shoes?"},{"sp":"A","zh":"長頭髮要綁起來，不可以穿拖鞋，要穿包鞋。","py":"cháng tóu fǎ yào bǎng qǐ lái bù kě yǐ chuān tuō xié yào chuān bāo xié","id":"Rambut panjang harus diikat, tidak boleh pakai sandal, harus sepatu tertutup.","en":"Long hair must be tied back, no slippers, and you must wear closed shoes."},{"sp":"B","zh":"如果不小心觸電或被燙到，要怎麼辦？","py":"rú guǒ bù xiǎo xīn chù diàn huò bèi tàng dào yào zěn me bàn","id":"Kalau tidak sengaja tersengat listrik atau terkena panas, bagaimana?","en":"What should we do if we get an electric shock or burned by accident?"},{"sp":"A","zh":"馬上關掉電源，然後通知我。急救箱放在門口旁邊。","py":"mǎ shàng guān diào diàn yuán rán hòu tōng zhī wǒ jí jiù xiāng fàng zài mén kǒu páng biān","id":"Segera matikan listrik, lalu beri tahu saya. Kotak P3K ada di samping pintu.","en":"Cut the power right away, then tell me. The first-aid kit is next to the door."},{"sp":"B","zh":"那滅火器和緊急停止按鈕在哪裡？","py":"nà miè huǒ qì hé jǐn jí tíng zhǐ àn niǔ zài nǎ lǐ","id":"Lalu alat pemadam api dan tombol darurat ada di mana?","en":"Then where are the fire extinguisher and the emergency stop button?"},{"sp":"A","zh":"滅火器在後門，緊急停止按鈕在每台機器的右邊。","py":"miè huǒ qì zài hòu mén jǐn jí tíng zhǐ àn niǔ zài měi tái jī qì de yòu biān","id":"Alat pemadam di pintu belakang, tombol darurat di sisi kanan tiap mesin.","en":"The extinguisher is at the back door, and the emergency stop is on the right of each machine."},{"sp":"B","zh":"了解。實驗室裡可以吃東西嗎？","py":"liǎo jiě shí yàn shì lǐ kě yǐ chī dōng xi ma","id":"Mengerti. Boleh makan di dalam lab?","en":"Understood. Can we eat in the lab?"},{"sp":"A","zh":"不行，飲料也不可以帶進來。這是為了你們的安全。","py":"bù xíng yǐn liào yě bù kě yǐ dài jìn lái zhè shì wèi le nǐ men de ān quán","id":"Tidak boleh, minuman juga tidak boleh dibawa masuk. Ini demi keselamatan kalian.","en":"No, and drinks can't be brought in either. This is for your own safety."}],"phrases":[{"zh":"安全規定","py":"ān quán guī dìng","id":"aturan keselamatan"},{"zh":"一定要戴護目鏡","py":"yí dìng yào dài hù mù jìng","id":"wajib memakai kacamata pelindung"},{"zh":"不小心觸電","py":"bù xiǎo xīn chù diàn","id":"tidak sengaja tersengat listrik"},{"zh":"馬上關掉電源","py":"mǎ shàng guān diào diàn yuán","id":"segera matikan listrik"},{"zh":"這是為了你們的安全","py":"zhè shì wèi le nǐ men de ān quán","id":"ini demi keselamatan kalian"}],"grammar":["bei","aux","zai"],"task":{"id":"Sebutkan tiga aturan keselamatan di laboratorium dan apa yang harus dilakukan saat terjadi kecelakaan listrik."}},{"id":"c_multimeter_oscilloscope","dom":"campus","lv":4,"title":{"zh":"用電表和示波器量測","id":"Mengukur dengan multimeter dan osiloskop","en":"Measuring with a multimeter and oscilloscope"},"goal":{"id":"Setelah ini kamu bisa melaporkan hasil ukur resistor dan sinyal dengan alat ukur di lab."},"lines":[{"sp":"A","zh":"你先用三用電表量一下這個電阻。","py":"nǐ xiān yòng sān yòng diàn biǎo liáng yí xià zhè ge diàn zǔ","id":"Ukur resistor ini dulu pakai multimeter.","en":"First measure this resistor with the multimeter."},{"sp":"B","zh":"好。我調到歐姆檔，現在顯示九點八千歐姆。","py":"hǎo wǒ tiáo dào ōu mǔ dàng xiàn zài xiǎn shì jiǔ diǎn bā qiān ōu mǔ","id":"Baik. Saya putar ke mode ohm, sekarang tertulis 9,8 kiloohm.","en":"Okay. I switched to the ohm range and it reads 9.8 kilo-ohms."},{"sp":"A","zh":"標示是一萬歐姆，誤差在百分之五以內，所以正常。","py":"biāo shì shì yí wàn ōu mǔ wù chā zài bǎi fēn zhī wǔ yǐ nèi suǒ yǐ zhèng cháng","id":"Labelnya 10 ribu ohm, toleransi dalam 5 persen, jadi normal.","en":"The label says 10,000 ohms and the error is within 5 percent, so it's normal."},{"sp":"B","zh":"接下來我要用示波器看訊號的波形。","py":"jiē xià lái wǒ yào yòng shì bō qì kàn xùn hào de bō xíng","id":"Selanjutnya saya mau lihat bentuk gelombang sinyal dengan osiloskop.","en":"Next I'll look at the signal waveform with the oscilloscope."},{"sp":"A","zh":"探棒要先校正，不然讀數會不準。","py":"tàn bàng yào xiān jiào zhèng bù rán dú shù huì bù zhǔn","id":"Probe harus dikalibrasi dulu, kalau tidak pembacaannya tidak akurat.","en":"The probe needs calibrating first, or the readings won't be accurate."},{"sp":"B","zh":"校正好了。頻率是一千赫茲，峰對峰電壓大概三點三伏特。","py":"jiào zhèng hǎo le pín lǜ shì yì qiān hè zī fēng duì fēng diàn yā dà gài sān diǎn sān fú tè","id":"Sudah dikalibrasi. Frekuensinya 1000 hertz, tegangan puncak ke puncak kira-kira 3,3 volt.","en":"Calibrated. The frequency is 1000 hertz and the peak-to-peak voltage is about 3.3 volts."},{"sp":"A","zh":"波形有沒有雜訊？","py":"bō xíng yǒu méi yǒu zá xùn","id":"Apakah gelombangnya ada noise?","en":"Is there any noise on the waveform?"},{"sp":"B","zh":"有一點，邊緣有些抖動，可能是接地沒接好。","py":"yǒu yì diǎn biān yuán yǒu xiē dǒu dòng kě néng shì jiē dì méi jiē hǎo","id":"Sedikit, bagian tepinya agak bergetar, mungkin groundnya kurang terhubung baik.","en":"A little. The edges jitter a bit, maybe the ground isn't connected well."},{"sp":"A","zh":"把地線夾在靠近電路的地方再量一次。","py":"bǎ dì xiàn jiá zài kào jìn diàn lù de dì fang zài liáng yí cì","id":"Jepit kabel ground di dekat rangkaian lalu ukur sekali lagi.","en":"Clip the ground lead close to the circuit and measure again."},{"sp":"B","zh":"重新量了，雜訊變少了，讀數穩定多了。","py":"chóng xīn liáng le zá xùn biàn shǎo le dú shù wěn dìng duō le","id":"Sudah diukur ulang, noise berkurang, pembacaan jauh lebih stabil.","en":"Measured again. The noise is lower and the reading is much more stable."}],"phrases":[{"zh":"量一下這個電阻","py":"liáng yí xià zhè ge diàn zǔ","id":"ukur resistor ini"},{"zh":"現在顯示……","py":"xiàn zài xiǎn shì","id":"sekarang menunjukkan ..."},{"zh":"誤差在百分之五以內","py":"wù chā zài bǎi fēn zhī wǔ yǐ nèi","id":"galat dalam 5 persen"},{"zh":"讀數不準","py":"dú shù bù zhǔn","id":"pembacaan tidak akurat"},{"zh":"讀數穩定多了","py":"dú shù wěn dìng duō le","id":"pembacaan jauh lebih stabil"}],"grammar":["le","degree","ba"],"task":{"id":"Laporkan hasil pengukuran sebuah resistor dan sinyal dari osiloskop kepada asisten lab."}},{"id":"c_solder_short_circuit","dom":"campus","lv":5,"title":{"zh":"焊接電路板與排除短路","id":"Menyolder PCB dan mencari korsleting","en":"Soldering a board and fixing a short circuit"},"goal":{"id":"Setelah ini kamu bisa menjelaskan masalah korsleting setelah menyolder dan cara memeriksanya."},"lines":[{"sp":"A","zh":"我焊好了，可是通電以後，電源指示燈沒有亮。","py":"wǒ hàn hǎo le kě shì tōng diàn yǐ hòu diàn yuán zhǐ shì dēng méi yǒu liàng","id":"Sudah selesai saya solder, tapi setelah dialiri listrik lampu indikator daya tidak menyala.","en":"I finished soldering, but after powering it on, the power LED didn't light up."},{"sp":"B","zh":"先斷電。用三用電表的蜂鳴檔量一下，看有沒有短路。","py":"xiān duàn diàn yòng sān yòng diàn biǎo de fēng míng dàng liáng yí xià kàn yǒu méi yǒu duǎn lù","id":"Matikan listrik dulu. Ukur dengan mode bunyi di multimeter, lihat ada korsleting atau tidak.","en":"Cut the power first. Use the multimeter's continuity beeper to check for a short."},{"sp":"A","zh":"電源正負極之間一直在響，真的短路了。","py":"diàn yuán zhèng fù jí zhī jiān yì zhí zài xiǎng zhēn de duǎn lù le","id":"Antara kutub positif dan negatif terus berbunyi, benar-benar korsleting.","en":"It keeps beeping between power positive and negative. It really is shorted."},{"sp":"B","zh":"你看一下板子，是不是有焊錫連在一起？","py":"nǐ kàn yí xià bǎn zi shì bú shì yǒu hàn xī lián zài yì qǐ","id":"Lihat papannya, apakah ada timah solder yang menyambung?","en":"Look at the board. Is there solder bridging somewhere?"},{"sp":"A","zh":"有，這兩個腳位中間有一顆小錫球。","py":"yǒu zhè liǎng ge jiǎo wèi zhōng jiān yǒu yì kē xiǎo xī qiú","id":"Ada, di antara dua kaki ini ada bola timah kecil.","en":"Yes, there's a small solder ball between these two pins."},{"sp":"B","zh":"用吸錫線把多餘的錫吸掉，再用放大鏡檢查。","py":"yòng xī xī xiàn bǎ duō yú de xī xī diào zài yòng fàng dà jìng jiǎn chá","id":"Serap kelebihan timah dengan kawat penyerap, lalu periksa dengan kaca pembesar.","en":"Wick away the extra solder with desoldering braid, then check with a magnifier."},{"sp":"A","zh":"好了，我再量一次，這次不會響了。","py":"hǎo le wǒ zài liáng yí cì zhè cì bú huì xiǎng le","id":"Sudah, saya ukur lagi, kali ini tidak berbunyi.","en":"Done. I measured again and this time it doesn't beep."},{"sp":"B","zh":"很好。通電以前，記得先確認電容有沒有裝反。","py":"hěn hǎo tōng diàn yǐ qián jì de xiān què rèn diàn róng yǒu méi yǒu zhuāng fǎn","id":"Bagus. Sebelum dialiri listrik, pastikan dulu kapasitornya tidak terpasang terbalik.","en":"Good. Before powering it on, check that no capacitor is installed backwards."},{"sp":"A","zh":"啊，這顆電解電容的極性好像反了，差點就爆了。","py":"a zhè kē diàn jiě diàn róng de jí xìng hǎo xiàng fǎn le chā diǎn jiù bào le","id":"Ah, polaritas kapasitor elektrolit ini sepertinya terbalik, hampir saja meledak.","en":"Ah, this electrolytic capacitor looks reversed. It almost blew up."},{"sp":"B","zh":"還好有先量過。焊的時候溫度不要太高，會燙壞零件。","py":"hái hǎo yǒu xiān liáng guò hàn de shí hòu wēn dù bú yào tài gāo huì tàng huài líng jiàn","id":"Untung sudah diukur dulu. Saat menyolder suhu jangan terlalu tinggi, bisa merusak komponen.","en":"Good thing we measured first. Don't set the temperature too high when soldering, or you'll burn the parts."}],"phrases":[{"zh":"電源指示燈沒亮","py":"diàn yuán zhǐ shì dēng méi liàng","id":"lampu indikator daya tidak menyala"},{"zh":"量一下有沒有短路","py":"liáng yí xià yǒu méi yǒu duǎn lù","id":"ukur apakah ada korsleting"},{"zh":"焊錫連在一起","py":"hàn xī lián zài yì qǐ","id":"timah solder menyambung"},{"zh":"差點就爆了","py":"chà diǎn jiù bào le","id":"hampir saja meledak"},{"zh":"還好有先量過","py":"hái hǎo yǒu xiān liáng guò","id":"untung sudah diukur dulu"}],"grammar":["ba","guo","le"],"task":{"id":"Ceritakan masalah rangkaian yang korsleting dan langkah-langkah yang kamu lakukan untuk memperbaikinya."}},{"id":"c_esp32_upload_fail","dom":"campus","lv":4,"title":{"zh":"微控制器程式上傳失敗","id":"Program ESP32 gagal diunggah","en":"Microcontroller (ESP32) upload fails"},"goal":{"id":"Setelah ini kamu bisa menjelaskan masalah gagal mengunggah program ke papan ESP32 dan mencari penyebabnya."},"lines":[{"sp":"A","zh":"同學，我的開發板程式上傳不進去，一直出現錯誤。","py":"tóng xué wǒ de kāi fā bǎn chéng shì shàng chuán bú jìn qù yì zhí chū xiàn cuò wù","id":"Teman, program di papan pengembangan saya tidak bisa diunggah, terus muncul error.","en":"Hey, my dev board won't take the program. It keeps showing an error."},{"sp":"B","zh":"錯誤訊息是什麼？","py":"cuò wù xùn xí shì shén me","id":"Pesan errornya apa?","en":"What does the error message say?"},{"sp":"A","zh":"上面寫連線逾時，沒辦法進入下載模式。","py":"shàng miàn xiě lián xiàn yú shí méi bàn fǎ jìn rù xià zài mó shì","id":"Tertulis koneksi timeout, tidak bisa masuk mode download.","en":"It says the connection timed out and it can't enter download mode."},{"sp":"B","zh":"你的傳輸線是不是只能充電，不能傳資料？","py":"nǐ de chuán shū xiàn shì bú shì zhǐ néng chōng diàn bù néng chuán zī liào","id":"Jangan-jangan kabelmu hanya untuk mengisi daya, tidak bisa transfer data?","en":"Is your cable charge-only, so it can't carry data?"},{"sp":"A","zh":"有可能，這條線是舊手機附的。","py":"yǒu kě néng zhè tiáo xiàn shì jiù shǒu jī fù de","id":"Mungkin, kabel ini bawaan HP lama.","en":"Possibly. This cable came with an old phone."},{"sp":"B","zh":"換一條試試看。還有，上傳的時候要按住板子上的啟動鍵。","py":"huàn yì tiáo shì shi kàn hái yǒu shàng chuán de shí hòu yào àn zhù bǎn zi shàng de qǐ dòng jiàn","id":"Coba ganti satu kabel. Lalu, saat mengunggah tahan tombol boot di papan.","en":"Try another one. Also, hold the boot button on the board while uploading."},{"sp":"A","zh":"換好了，也按住了，這次顯示正在燒錄。","py":"huàn hǎo le yě àn zhù le zhè cì xiǎn shì zhèng zài shāo lù","id":"Sudah ganti dan saya tahan tombolnya, kali ini tertulis sedang menulis program.","en":"Swapped it and held the button. This time it says it's flashing."},{"sp":"B","zh":"太好了。燒錄完成後，記得按重置鍵，程式才會開始跑。","py":"tài hǎo le shāo lù wán chéng hòu jì de àn chóng zhì jiàn chéng shì cái huì kāi shǐ pǎo","id":"Bagus. Setelah selesai, ingat tekan tombol reset, baru programnya mulai berjalan.","en":"Great. After flashing, remember to press reset so the program starts running."},{"sp":"A","zh":"燈真的閃了！謝謝你，我差點以為板子壞了。","py":"dēng zhēn de shǎn le xiè xie nǐ wǒ chà diǎn yǐ wéi bǎn zi huài le","id":"Lampunya benar-benar berkedip! Terima kasih, saya hampir mengira papannya rusak.","en":"The LED is blinking! Thanks, I almost thought the board was broken."}],"phrases":[{"zh":"程式上傳不進去","py":"chéng shì shàng chuán bú jìn qù","id":"program tidak bisa diunggah"},{"zh":"錯誤訊息是什麼？","py":"cuò wù xùn xí shì shén me","id":"pesan errornya apa?"},{"zh":"只能充電，不能傳資料","py":"zhǐ néng chōng diàn bù néng chuán zī liào","id":"hanya bisa mengisi daya, tidak bisa transfer data"},{"zh":"換一條試試看","py":"huàn yì tiáo shì shi kàn","id":"coba ganti satu"},{"zh":"程式才會開始跑","py":"chéng shì cái huì kāi shǐ pǎo","id":"baru programnya mulai berjalan"}],"grammar":["order","le","aux"],"task":{"id":"Jelaskan kepada temanmu bahwa programmu gagal diunggah ke papan mikrokontroler dan sebutkan dua hal yang akan kamu periksa."}},{"id":"c_plc_pneumatics_ta","dom":"campus","lv":5,"title":{"zh":"可程式控制器與氣壓實驗","id":"Praktikum PLC dan pneumatik dengan asisten","en":"PLC and pneumatics lab with the TA"},"goal":{"id":"Setelah ini kamu bisa memahami instruksi asisten dalam praktikum PLC dan pneumatik serta memeriksa kebocoran udara."},"lines":[{"sp":"A","zh":"今天的實驗是用可程式控制器來控制氣壓缸。","py":"jīn tiān de shí yàn shì yòng kě chéng shì kòng zhì qì lái kòng zhì qì yā gāng","id":"Praktikum hari ini mengendalikan silinder pneumatik dengan PLC.","en":"Today's lab uses a programmable controller to drive a pneumatic cylinder."},{"sp":"B","zh":"助教，我們要先接氣管嗎？","py":"zhù jiào wǒ men yào xiān jiē qì guǎn ma","id":"Kak asisten, apakah kami harus memasang selang udara dulu?","en":"TA, do we connect the air hose first?"},{"sp":"A","zh":"對，先把氣管接到電磁閥，再打開空壓機。","py":"duì xiān bǎ qì guǎn jiē dào diàn cí fá zài dǎ kāi kōng yā jī","id":"Betul, sambungkan selang ke katup solenoid dulu, baru nyalakan kompresor.","en":"Right, connect the hose to the solenoid valve first, then switch on the compressor."},{"sp":"B","zh":"壓力表現在是六公斤，這樣可以嗎？","py":"yā lì biǎo xiàn zài shì liù gōng jīn zhè yàng kě yǐ ma","id":"Pengukur tekanan sekarang enam kg (kgf/cm²), apakah ini sudah benar?","en":"The pressure gauge reads 6 kg now. Is that OK?"},{"sp":"A","zh":"可以，不過要先檢查有沒有漏氣。","py":"kě yǐ bú guò yào xiān jiǎn chá yǒu méi yǒu lòu qì","id":"Boleh, tapi periksa dulu apakah ada kebocoran udara.","en":"Yes, but check for air leaks first."},{"sp":"B","zh":"我聽到這邊有嘶嘶的聲音，是接頭沒有鎖緊嗎？","py":"wǒ tīng dào zhè biān yǒu sī sī de shēng yīn shì jiē tóu méi yǒu suǒ jǐn ma","id":"Saya dengar suara desis di sini, apa sambungannya belum dikencangkan?","en":"I hear a hissing sound here. Is the fitting not tightened?"},{"sp":"A","zh":"對，先洩壓再重新接。程式寫好了嗎？","py":"duì xiān xiè yā zài chóng xīn jiē chéng shì xiě hǎo le ma","id":"Ya, lepas tekanan dulu lalu pasang ulang. Programnya sudah selesai?","en":"Yes, release the pressure first and reconnect. Is the program done?"},{"sp":"B","zh":"寫好了，按下啟動按鈕，氣壓缸就會伸出去。","py":"xiě hǎo le àn xià qǐ dòng àn niǔ qì yā gāng jiù huì shēn chū qù","id":"Sudah, begitu tombol start ditekan silindernya akan keluar.","en":"Yes. When I press the start button, the cylinder extends."},{"sp":"A","zh":"要加上極限開關，讓它碰到就自動縮回來。","py":"yào jiā shàng jí xiàn kāi guān ràng tā pèng dào jiù zì dòng suō huí lái","id":"Tambahkan saklar batas supaya begitu tersentuh otomatis menarik kembali.","en":"Add a limit switch so it retracts automatically when it touches it."},{"sp":"B","zh":"好，我把感測器的訊號接到輸入點。","py":"hǎo wǒ bǎ gǎn cè qì de xùn hào jiē dào shū rù diǎn","id":"Baik, saya sambungkan sinyal sensor ke titik input.","en":"Okay, I'll wire the sensor signal to the input terminal."},{"sp":"A","zh":"沒錯，測試的時候手不要伸進去，很危險。","py":"méi cuò cè shì de shí hòu shǒu bú yào shēn jìn qù hěn wéi xiǎn","id":"Benar, saat uji coba jangan julurkan tangan ke dalam, bahaya.","en":"Exactly. Don't put your hand in during testing, it's dangerous."}],"phrases":[{"zh":"先檢查有沒有漏氣","py":"xiān jiǎn chá yǒu méi yǒu lòu qì","id":"periksa dulu apakah ada kebocoran udara"},{"zh":"接頭沒有鎖緊","py":"jiē tóu méi yǒu suǒ jǐn","id":"sambungan belum dikencangkan"},{"zh":"先洩壓再重新接","py":"xiān xiè yā zài chóng xīn jiē","id":"lepas tekanan dulu lalu pasang ulang"},{"zh":"按下啟動按鈕","py":"àn xià qǐ dòng àn niǔ","id":"tekan tombol start"},{"zh":"手不要伸進去","py":"shǒu bú yào shēn jìn qù","id":"jangan julurkan tangan ke dalam"}],"grammar":["ba","order","le"],"task":{"id":"Jelaskan urutan langkah menyiapkan silinder pneumatik dari menyambung selang sampai menguji program."}},{"id":"c_exam_scope_grades","dom":"campus","lv":4,"title":{"zh":"討論考試範圍與成績","id":"Membahas cakupan ujian dan nilai","en":"Discussing exam scope and grades"},"goal":{"id":"Setelah ini kamu bisa menanyakan cakupan ujian, jenis soal, dan cara penilaian kepada dosen."},"lines":[{"sp":"A","zh":"老師，期中考的範圍是從第一章到第五章嗎？","py":"lǎo shī qí zhōng kǎo de fàn wéi shì cóng dì yī zhāng dào dì wǔ zhāng ma","id":"Pak/Bu, cakupan UTS dari bab satu sampai bab lima?","en":"Professor, does the midterm cover Chapter 1 to Chapter 5?"},{"sp":"B","zh":"對，不過第五章只考前半部。","py":"duì bú guò dì wǔ zhāng zhǐ kǎo qián bàn bù","id":"Ya, tapi bab lima hanya separuh pertama yang diujikan.","en":"Yes, but only the first half of Chapter 5 is tested."},{"sp":"A","zh":"考試會有計算題嗎？","py":"kǎo shì huì yǒu jì suàn tí ma","id":"Apakah ujiannya ada soal hitungan?","en":"Will there be calculation questions?"},{"sp":"B","zh":"會，大概占百分之四十，其他是選擇題和簡答題。","py":"huì dà gài zhàn bǎi fēn zhī sì shí qí tā shì xuǎn zé tí hé jiǎn dá tí","id":"Ada, sekitar 40 persen, sisanya pilihan ganda dan jawaban singkat.","en":"Yes, about 40 percent. The rest is multiple choice and short answer."},{"sp":"A","zh":"可以帶計算機嗎？還是只能帶公式表？","py":"kě yǐ dài jì suàn jī ma hái shi zhǐ néng dài gōng shì biǎo","id":"Boleh bawa kalkulator? Atau hanya boleh membawa tabel rumus?","en":"Can we bring a calculator, or only a formula sheet?"},{"sp":"B","zh":"可以帶計算機，公式表我會在考卷後面附上。","py":"kě yǐ dài jì suàn jī gōng shì biǎo wǒ huì zài kǎo juàn hòu miàn fù shàng","id":"Boleh bawa kalkulator, tabel rumus saya lampirkan di belakang lembar soal.","en":"You can bring a calculator. I'll attach the formula sheet at the back of the exam."},{"sp":"A","zh":"那學期成績是怎麼算的呢？","py":"nà xué qí chéng jī shì zěn me suàn de ne","id":"Lalu nilai semester dihitung bagaimana?","en":"Then how is the semester grade calculated?"},{"sp":"B","zh":"期中和期末各占百分之三十，平時成績和報告占四成。","py":"qí zhōng hé qí mò gè zhàn bǎi fēn zhī sān shí píng shí chéng jī hé bào gào zhàn sì chéng","id":"UTS dan UAS masing-masing 30 persen, nilai harian dan laporan 40 persen.","en":"Midterm and final are 30 percent each, and daily work plus reports make up 40 percent."},{"sp":"A","zh":"如果我期中考不理想，期末還有機會補救嗎？","py":"rú guǒ wǒ qí zhōng kǎo bù lǐ xiǎng qí mò hái yǒu jī huì bǔ jiù ma","id":"Kalau UTS saya kurang bagus, apakah UAS masih bisa memperbaiki?","en":"If my midterm doesn't go well, can I still make up for it in the final?"},{"sp":"B","zh":"有，只要期末表現好，分數還是可以拉起來。","py":"yǒu zhǐ yào qí mò biǎo xiàn hǎo fēn shù hái shi kě yǐ lā qǐ lái","id":"Bisa, asal UAS bagus, nilainya masih bisa dinaikkan.","en":"Yes, as long as you do well in the final, your grade can still come up."},{"sp":"A","zh":"我知道了，謝謝老師，我會好好準備。","py":"wǒ zhī dào le xiè xie lǎo shī wǒ huì hǎo hǎo zhǔn bèi","id":"Saya mengerti, terima kasih, saya akan mempersiapkan diri baik-baik.","en":"Got it. Thank you, Professor, I'll prepare well."}],"phrases":[{"zh":"考試的範圍","py":"kǎo shì de fàn wéi","id":"cakupan ujian"},{"zh":"可以帶計算機嗎？","py":"kě yǐ dài jì suàn jī ma","id":"boleh bawa kalkulator?"},{"zh":"學期成績是怎麼算的？","py":"xué qí chéng jī shì zěn me suàn de","id":"nilai semester dihitung bagaimana?"},{"zh":"考得不理想","py":"kǎo de bù lǐ xiǎng","id":"hasil ujian kurang memuaskan"},{"zh":"分數可以拉起來","py":"fēn shù kě yǐ lā qǐ lái","id":"nilai masih bisa dinaikkan"}],"grammar":["shi","de","qw"],"task":{"id":"Tanyakan kepada dosen tentang cakupan ujian dan komposisi nilai mata kuliahmu."}},{"id":"c_internship_advisor","dom":"campus","lv":5,"title":{"zh":"與導師談實習申請","id":"Membicarakan lamaran magang dengan dosen pembimbing","en":"Talking to an advisor about an internship"},"goal":{"id":"Setelah ini kamu bisa meminta saran dosen pembimbing soal lamaran magang di industri semikonduktor."},"lines":[{"sp":"A","zh":"老師，我想申請暑假的實習，可以請您給我一些建議嗎？","py":"lǎo shī wǒ xiǎng shēn qǐng shǔ jià de shí xí kě yǐ qǐng nín gěi wǒ yì xiē jiàn yì ma","id":"Pak/Bu, saya ingin melamar magang liburan musim panas, boleh minta saran?","en":"Professor, I'd like to apply for a summer internship. Could you give me some advice?"},{"sp":"B","zh":"當然。你對哪一類的公司比較有興趣？","py":"dāng rán nǐ duì nǎ yí lèi de gōng sī bǐ jiào yǒu xìng qù","id":"Tentu. Perusahaan jenis apa yang lebih kamu minati?","en":"Of course. What kind of company are you more interested in?"},{"sp":"A","zh":"我想去半導體封裝測試廠，學習機台的維修和保養。","py":"wǒ xiǎng qù bàn dǎo tǐ fēng zhuāng cè shì chǎng xué xí jī tái de wéi xiū hé bǎo yǎng","id":"Saya ingin ke pabrik pengemasan dan pengujian semikonduktor, belajar perbaikan dan perawatan mesin.","en":"I'd like to go to a semiconductor packaging and testing plant and learn machine repair and maintenance."},{"sp":"B","zh":"很好。那你的履歷和自傳寫好了嗎？","py":"hěn hǎo nà nǐ de lǚ lì hé zì zhuàn xiě hǎo le ma","id":"Bagus. Lalu CV dan autobiografimu sudah selesai?","en":"Good. Have you finished your résumé and personal statement?"},{"sp":"A","zh":"履歷寫好了，但自傳我還不知道該怎麼寫。","py":"lǚ lì xiě hǎo le dàn zì zhuàn wǒ hái bù zhī dào gāi zěn me xiě","id":"CV sudah, tapi autobiografinya saya belum tahu harus menulis bagaimana.","en":"The résumé is done, but I don't know yet how to write the personal statement."},{"sp":"B","zh":"重點是要說明你為什麼想做這份工作，還有你學過什麼。","py":"zhòng diǎn shì yào shuō míng nǐ wèi shén me xiǎng zuò zhè fèn gōng zuò hái yǒu nǐ xué guò shén me","id":"Intinya jelaskan kenapa kamu mau pekerjaan ini dan apa yang sudah kamu pelajari.","en":"The key is to explain why you want this job and what you've studied."},{"sp":"A","zh":"我的中文還不夠流利，面試的時候會不會有問題？","py":"wǒ de zhōng wén hái bú gòu liú lì miàn shì de shí hòu huì bú huì yǒu wèn tí","id":"Bahasa Mandarin saya belum cukup lancar, apakah akan bermasalah saat wawancara?","en":"My Chinese isn't fluent enough yet. Will that be a problem in the interview?"},{"sp":"B","zh":"不用太擔心，只要你態度認真，願意學習，公司都會看到。","py":"bú yòng tài dān xīn zhǐ yào nǐ tài dù rèn zhēn yuàn yì xué xí gōng sī dōu huì kàn dào","id":"Jangan terlalu khawatir, asal sikapmu serius dan mau belajar, perusahaan akan melihatnya.","en":"Don't worry too much. As long as you're serious and willing to learn, companies will see it."},{"sp":"A","zh":"那面試前，我可以先找您練習一下嗎？","py":"nà miàn shì qián wǒ kě yǐ xiān zhǎo nín liàn xí yí xià ma","id":"Kalau begitu sebelum wawancara, boleh saya berlatih dulu dengan Anda?","en":"Then before the interview, may I come practice with you?"},{"sp":"B","zh":"可以，你先把履歷寄給我，我幫你看過再約時間。","py":"kě yǐ nǐ xiān bǎ lǚ lì jì gěi wǒ wǒ bāng nǐ kàn guò zài yuē shí jiān","id":"Boleh, kirim CV-mu dulu, setelah saya periksa kita atur waktunya.","en":"Sure. Send me your résumé first, and I'll look it over before we set a time."}],"phrases":[{"zh":"申請暑假的實習","py":"shēn qǐng shǔ jià de shí xí","id":"melamar magang liburan musim panas"},{"zh":"給我一些建議","py":"gěi wǒ yì xiē jiàn yì","id":"beri saya beberapa saran"},{"zh":"履歷和自傳","py":"lǚ lì hé zì zhuàn","id":"CV dan autobiografi"},{"zh":"我對……有興趣","py":"wǒ duì yǒu xìng qù","id":"saya tertarik pada ..."},{"zh":"只要你態度認真","py":"zhǐ yào nǐ tài dù rèn zhēn","id":"asal sikapmu serius"}],"grammar":["ba","aux","qw"],"task":{"id":"Ceritakan kepada dosen pembimbing perusahaan seperti apa yang ingin kamu lamar untuk magang dan alasannya."}},{"id":"c_explain_lab_report","dom":"campus","lv":5,"title":{"zh":"向老師說明實驗報告結果","id":"Menjelaskan hasil laporan praktikum kepada dosen","en":"Explaining lab report results to the teacher"},"goal":{"id":"Setelah ini kamu bisa menjelaskan hasil praktikum, dugaan penyebab, dan kekurangannya kepada dosen."},"lines":[{"sp":"A","zh":"老師，我想跟您說明一下實驗報告的結果。","py":"lǎo shī wǒ xiǎng gēn nín shuō míng yí xià shí yàn bào gào de jié guǒ","id":"Pak/Bu, saya ingin menjelaskan hasil laporan praktikum.","en":"Professor, I'd like to explain the results of my lab report."},{"sp":"B","zh":"好，你說說看。這次是量二極體的特性曲線，對吧？","py":"hǎo nǐ shuō shuo kàn zhè cì shì liáng èr jí tǐ de tè xìng qū xiàn duì ba","id":"Baik, coba jelaskan. Kali ini mengukur kurva karakteristik dioda, kan?","en":"Okay, go ahead. This time you measured a diode's characteristic curve, right?"},{"sp":"A","zh":"對。我們發現順向電壓大約是零點七伏特，跟理論值差不多。","py":"duì wǒ men fā xiàn shùn xiàng diàn yā dà yuē shì líng diǎn qī fú tè gēn lǐ lùn zhí chà bù duō","id":"Ya. Kami temukan tegangan maju sekitar 0,7 volt, hampir sama dengan nilai teori.","en":"Yes. We found the forward voltage is about 0.7 volts, close to the theoretical value."},{"sp":"B","zh":"那逆向漏電流呢？","py":"nà nì xiàng lòu diàn liú ne","id":"Lalu arus bocor baliknya?","en":"And the reverse leakage current?"},{"sp":"A","zh":"比預期的大，我們推測是因為溫度升高了。","py":"bǐ yù qí de dà wǒ men tuī cè shì yīn wèi wēn dù shēng gāo le","id":"Lebih besar dari perkiraan, kami menduga karena suhunya naik.","en":"It was larger than expected. We guess it's because the temperature rose."},{"sp":"B","zh":"這個推測合理，但你們有沒有量溫度來驗證？","py":"zhè ge tuī cè hé lǐ dàn nǐ men yǒu méi yǒu liáng wēn dù lái yàn zhèng","id":"Dugaan itu masuk akal, tapi apakah kalian mengukur suhu untuk membuktikannya?","en":"That's a reasonable guess, but did you measure the temperature to verify it?"},{"sp":"A","zh":"沒有，這是我們實驗設計的缺點，下次會改進。","py":"méi yǒu zhè shì wǒ men shí yàn shè jì de quē diǎn xià cì huì gǎi jìn","id":"Tidak, ini kekurangan desain percobaan kami, lain kali akan diperbaiki.","en":"No, that's a flaw in our experiment design. We'll improve it next time."},{"sp":"B","zh":"另外，誤差分析的部分太簡單了，要說明誤差是從哪裡來的。","py":"lìng wài wù chā fēn xī de bù fèn tài jiǎn dān le yào shuō míng wù chā shì cóng nǎ lǐ lái de","id":"Selain itu, bagian analisis galat terlalu sederhana, harus dijelaskan dari mana galat itu berasal.","en":"Also, the error analysis is too simple. You need to explain where the error comes from."},{"sp":"A","zh":"我了解。是要寫儀器的精確度，還有人為讀數的誤差嗎？","py":"wǒ liǎo jiě shì yào xiě yí qì de jīng què dù hái yǒu rén wéi dú shù de wù chā ma","id":"Saya mengerti. Maksudnya ditulis ketelitian alat dan galat pembacaan manusia?","en":"I see. Should I write about the instrument precision and human reading errors?"},{"sp":"B","zh":"對，補充之後再交給我，我會重新評分。","py":"duì bǔ chōng zhī hòu zài jiāo gěi wǒ wǒ huì chóng xīn píng fēn","id":"Betul, setelah dilengkapi serahkan lagi kepada saya, nanti saya nilai ulang.","en":"Right. Add that and hand it back to me, and I'll regrade it."},{"sp":"A","zh":"好，我今晚就修改，明天一早傳給您。","py":"hǎo wǒ jīn wǎn jiù xiū gǎi míng tiān yì zǎo chuán gěi nín","id":"Baik, malam ini saya revisi dan besok pagi-pagi saya kirim.","en":"Okay, I'll revise it tonight and send it to you first thing tomorrow."}],"phrases":[{"zh":"跟您說明一下結果","py":"gēn nín shuō míng yí xià jié guǒ","id":"menjelaskan hasilnya kepada Anda"},{"zh":"跟理論值差不多","py":"gēn lǐ lùn zhí chà bù duō","id":"hampir sama dengan nilai teori"},{"zh":"我們推測是因為……","py":"wǒ men tuī cè shì yīn wèi","id":"kami menduga karena ..."},{"zh":"誤差是從哪裡來的","py":"wù chā shì cóng nǎ lǐ lái de","id":"dari mana galat itu berasal"},{"zh":"下次會改進","py":"xià cì huì gǎi jìn","id":"lain kali akan diperbaiki"}],"grammar":["bi","yinwei","le"],"task":{"id":"Jelaskan satu hasil praktikum, dugaan penyebabnya, dan satu kekurangan eksperimenmu kepada dosen."}},{"id":"f_gowning_first_day","dom":"fab","lv":4,"title":{"zh":"第一天與無塵室更衣","id":"Hari pertama dan aturan ganti baju cleanroom","en":"First day and cleanroom gowning"},"goal":{"id":"Setelah ini kamu bisa memahami dan menanyakan aturan ganti baju cleanroom di hari pertama kerja."},"lines":[{"sp":"A","zh":"歡迎加入！我是負責帶你的學長，叫我阿志就好。","py":"huān yíng jiā rù wǒ shì fù zé dài nǐ de xué zhǎng jiào wǒ ā zhì jiù hǎo","id":"Selamat bergabung! Aku senior yang membimbingmu, panggil saja Azhi.","en":"Welcome aboard! I'm the senior in charge of training you. Just call me A-Zhi."},{"sp":"B","zh":"學長好，我是新來的實習生，今天第一天上班，有點緊張。","py":"xué zhǎng hǎo wǒ shì xīn lái de shí xí shēng jīn tiān dì yī tiān shàng bān yǒu diǎn jǐn zhāng","id":"Halo Kak, aku anak magang baru, hari ini hari pertama kerja, agak gugup.","en":"Hi senior, I'm the new intern. It's my first day and I'm a bit nervous."},{"sp":"A","zh":"不用緊張。進無塵室之前要先換無塵衣，我帶你去更衣室。","py":"bú yòng jǐn zhāng jìn wú chén shì zhī qián yào xiān huàn wú chén yī wǒ dài nǐ qù gèng yī shì","id":"Tidak perlu gugup. Sebelum masuk cleanroom harus ganti baju cleanroom dulu, aku antar ke ruang ganti.","en":"No need to be nervous. Before entering the cleanroom you have to change into a cleanroom suit. I'll take you to the changing room."},{"sp":"B","zh":"好。要先脫外套嗎？還是直接穿上去？","py":"hǎo yào xiān tuō wài tào ma hái shì zhí jiē chuān shàng qù","id":"Baik. Jaket dilepas dulu? Atau langsung dipakai di atasnya?","en":"OK. Do I take off my jacket first, or just put it on over?"},{"sp":"A","zh":"外套和包包都要放進置物櫃，只能帶識別證和手套進去。","py":"wài tào hé bāo bāo dōu yào fàng jìn zhì wù guì zhǐ néng dài shí bié zhèng hé shǒu tào jìn qù","id":"Jaket dan tas harus disimpan di loker, hanya boleh bawa kartu identitas dan sarung tangan.","en":"Jackets and bags go in the locker. You can only bring your ID badge and gloves in."},{"sp":"B","zh":"手機也不能帶嗎？","py":"shǒu jī yě bù néng dài ma","id":"HP juga tidak boleh dibawa?","en":"Can't I bring my phone either?"},{"sp":"A","zh":"手機不能帶進去，無塵室裡只能用公司的專用手機。","py":"shǒu jī bù néng dài jìn qù wú chén shì lǐ zhǐ néng yòng gōng sī de zhuān yòng shǒu jī","id":"HP tidak boleh dibawa masuk, di dalam cleanroom hanya boleh pakai HP khusus perusahaan.","en":"You can't bring your phone in. Inside the cleanroom you can only use the company's dedicated phones."},{"sp":"A","zh":"穿的順序是先戴頭套和口罩，再穿無塵衣，最後穿無塵鞋、戴手套。","py":"chuān de shùn xù shì xiān dài tóu tào hé kǒu zhào zài chuān wú chén yī zuì hòu chuān wú chén xié dài shǒu tào","id":"Urutannya: penutup kepala dan masker dulu, lalu baju cleanroom, terakhir sepatu cleanroom dan sarung tangan.","en":"The order is: hood and mask first, then the cleanroom suit, and finally cleanroom boots and gloves."},{"sp":"B","zh":"拉鍊要拉到最上面嗎？頭髮可以露出來嗎？","py":"lā liàn yào lā dào zuì shàng miàn ma tóu fǎ kě yǐ lòu chū lái ma","id":"Ritsletingnya harus ditarik sampai paling atas? Rambut boleh kelihatan?","en":"Do I zip it all the way up? Can my hair show?"},{"sp":"A","zh":"要拉到最上面，頭髮一根都不能露出來。進去之前還要過風淋室，把身上的灰塵吹掉。","py":"yào lā dào zuì shàng miàn tóu fǎ yì gēn dōu bù néng lòu chū lái jìn qù zhī qián hái yào guò fēng lín shì bǎ shēn shàng de huī chén chuī diào","id":"Harus sampai paling atas, sehelai rambut pun tidak boleh kelihatan. Sebelum masuk juga harus lewat air shower untuk meniup debu dari badan.","en":"Zip it all the way up, and not a single hair can show. Before going in you also pass through the air shower to blow off dust."},{"sp":"B","zh":"了解。如果無塵衣弄髒了怎麼辦？","py":"liǎo jiě rú guǒ wú chén yī nòng zāng le zěn me bàn","id":"Mengerti. Kalau baju cleanroom-nya kotor bagaimana?","en":"Got it. What if the cleanroom suit gets dirty?"},{"sp":"A","zh":"馬上出來換新的，千萬不要硬穿，會影響產品。","py":"mǎ shàng chū lái huàn xīn de qiān wàn bú yào yìng chuān huì yǐng xiǎng chǎn pǐn","id":"Segera keluar dan ganti yang baru, jangan dipaksa pakai, bisa memengaruhi produk.","en":"Come out right away and change into a new one. Never just keep wearing it, it affects the product."}],"phrases":[{"zh":"進無塵室之前要先換無塵衣","py":"jìn wú chén shì zhī qián yào xiān huàn wú chén yī","id":"Sebelum masuk cleanroom harus ganti baju cleanroom dulu"},{"zh":"頭髮一根都不能露出來","py":"tóu fǎ yì gēn dōu bù néng lòu chū lái","id":"Sehelai rambut pun tidak boleh kelihatan"},{"zh":"要過風淋室","py":"yào guò fēng lín shì","id":"Harus lewat air shower"},{"zh":"把身上的灰塵吹掉","py":"bǎ shēn shàng de huī chén chuī diào","id":"Meniup debu dari badan"},{"zh":"千萬不要硬穿","py":"qiān wàn bú yào yìng chuān","id":"Jangan sekali-kali dipaksa pakai"}],"grammar":["ba","aux"],"task":{"id":"Jelaskan kepada teman baru urutan memakai baju cleanroom dan apa saja yang tidak boleh dibawa masuk."}},{"id":"f_shift_handover","dom":"fab","lv":4,"title":{"zh":"交接班","id":"Serah terima shift","en":"Shift handover"},"goal":{"id":"Setelah ini kamu bisa menyampaikan dan menerima informasi saat serah terima shift."},"lines":[{"sp":"A","zh":"早，我來跟你交接一下，昨天夜班有幾件事要跟你說。","py":"zǎo wǒ lái gēn nǐ jiāo jiē yí xià zuó tiān yè bān yǒu jǐ jiàn shì yào gēn nǐ shuō","id":"Pagi, aku serah terima ke kamu ya, shift malam kemarin ada beberapa hal yang perlu kuberitahu.","en":"Morning. Let me hand over to you. There are a few things from last night's shift."},{"sp":"B","zh":"好，你說，我邊聽邊記。","py":"hǎo nǐ shuō wǒ biān tīng biān jì","id":"Oke, silakan, aku catat sambil dengar.","en":"OK, go ahead. I'll take notes as you talk."},{"sp":"A","zh":"第三台蝕刻機凌晨兩點跳了一次警報，後來重開機就恢復了。","py":"dì sān tái shí kè jī líng chén liǎng diǎn tiào le yí cì jǐng bào hòu lái chóng kāi jī jiù huī fù le","id":"Mesin etching nomor tiga alarm sekali jam dua dini hari, lalu pulih setelah di-restart.","en":"Etcher number three threw an alarm once at 2 a.m. and recovered after a restart."},{"sp":"B","zh":"有通知設備工程師嗎？","py":"yǒu tōng zhī shè bèi gōng chéng shī ma","id":"Sudah memberi tahu insinyur peralatan?","en":"Did you notify the equipment engineer?"},{"sp":"A","zh":"有，他說先觀察，如果再發生就要停機檢查。紀錄我寫在交接單上了。","py":"yǒu tā shuō xiān guān chá rú guǒ zài fā shēng jiù yào tíng jī jiǎn chá jì lù wǒ xiě zài jiāo jiē dān shàng le","id":"Sudah, katanya diamati dulu, kalau terjadi lagi harus dihentikan untuk diperiksa. Catatannya sudah kutulis di lembar serah terima.","en":"Yes. He said to observe first, and if it happens again to stop the machine and check. I wrote the record on the handover sheet."},{"sp":"B","zh":"好。那現在有沒有被卡住的貨？","py":"hǎo nà xiàn zài yǒu méi yǒu bèi qiǎ zhù de huò","id":"Oke. Sekarang ada lot yang tertahan?","en":"OK. Are there any lots on hold right now?"},{"sp":"A","zh":"有兩批在等光阻檢查，其中一批已經超過八小時了，要盡快處理。","py":"yǒu liǎng pī zài děng guāng zǔ jiǎn chá qí zhōng yì pī yǐ jīng chāo guò bā xiǎo shí le yào jìn kuài chǔ lǐ","id":"Ada dua lot menunggu pemeriksaan photoresist, salah satunya sudah lewat delapan jam, harus segera ditangani.","en":"Two lots are waiting for resist inspection. One has already passed eight hours, so it needs handling soon."},{"sp":"B","zh":"好，我一上班就先看那兩批。","py":"hǎo wǒ yí shàng bān jiù xiān kàn nà liǎng pī","id":"Oke, begitu mulai kerja aku langsung cek dua lot itu.","en":"OK, the first thing I do after clocking in is look at those two lots."},{"sp":"A","zh":"還有，五樓的氣體偵測器昨天被人誤觸，已經報修了。","py":"hái yǒu wǔ lóu de qì tǐ zhēn cè qì zuó tiān bèi rén wù chù yǐ jīng bào xiū le","id":"Lalu, detektor gas di lantai lima kemarin tersentuh tidak sengaja, sudah dilaporkan untuk diperbaiki.","en":"Also, the gas detector on the fifth floor was triggered by accident yesterday and has been reported for repair."},{"sp":"B","zh":"收到。還有別的嗎？","py":"shōu dào hái yǒu bié de ma","id":"Diterima. Ada yang lain?","en":"Got it. Anything else?"},{"sp":"A","zh":"差不多就這些，剩下的都在交接單上，有問題再打給我。","py":"chà bu duō jiù zhè xiē shèng xià de dōu zài jiāo jiē dān shàng yǒu wèn tí zài dǎ gěi wǒ","id":"Kurang lebih itu saja, sisanya ada di lembar serah terima, kalau ada masalah telepon aku.","en":"That's about it. The rest is on the handover sheet. Call me if you have questions."},{"sp":"B","zh":"好，辛苦了，你快回去休息吧。","py":"hǎo xīn kǔ le nǐ kuài huí qù xiū xí ba","id":"Oke, terima kasih atas kerja kerasnya, cepat pulang istirahat ya.","en":"OK, thanks for your hard work. Go home and get some rest."}],"phrases":[{"zh":"我來跟你交接一下","py":"wǒ lái gēn nǐ jiāo jiē yí xià","id":"Aku serah terima ke kamu sebentar ya"},{"zh":"重開機就恢復了","py":"chóng kāi jī jiù huī fù le","id":"Setelah di-restart langsung pulih"},{"zh":"紀錄我寫在交接單上了","py":"jì lù wǒ xiě zài jiāo jiē dān shàng le","id":"Catatannya sudah kutulis di lembar serah terima"},{"zh":"有問題再打給我","py":"yǒu wèn tí zài dǎ gěi wǒ","id":"Kalau ada masalah telepon aku lagi"},{"zh":"辛苦了","py":"xīn kǔ le","id":"Terima kasih atas kerja kerasnya"}],"grammar":["bei","yibian"],"task":{"id":"Bayangkan kamu shift malam. Sampaikan kepada rekan shift pagi apa yang terjadi pada mesin dan lot malam tadi."}},{"id":"f_machine_alarm_report","dom":"fab","lv":4,"title":{"zh":"機台警報與通報工程師","id":"Alarm mesin dan lapor ke insinyur","en":"Machine alarm and reporting to the engineer"},"goal":{"id":"Setelah ini kamu bisa melaporkan alarm mesin dengan jelas kepada insinyur peralatan."},"lines":[{"sp":"B","zh":"工程師，不好意思，三號機台剛剛跳警報了。","py":"gōng chéng shī bù hǎo yì si sān hào jī tái gāng gāng tiào jǐng bào le","id":"Pak insinyur, maaf, mesin nomor tiga barusan alarm.","en":"Engineer, sorry to bother you, tool number three just threw an alarm."},{"sp":"A","zh":"什麼警報？螢幕上顯示什麼代碼？","py":"shén me jǐng bào yíng mù shàng xiǎn shì shén me dài mǎ","id":"Alarm apa? Kode apa yang tampil di layar?","en":"What alarm? What code is on the screen?"},{"sp":"B","zh":"是真空壓力異常，腔體壓力一直降不下來。","py":"shì zhēn kōng yā lì yì cháng qiāng tǐ yā lì yì zhí jiàng bu xià lái","id":"Tekanan vakum abnormal, tekanan chamber terus tidak bisa turun.","en":"It's a vacuum pressure fault. The chamber pressure just won't come down."},{"sp":"A","zh":"你有先按停止嗎？貨還在裡面嗎？","py":"nǐ yǒu xiān àn tíng zhǐ ma huò hái zài lǐ miàn ma","id":"Sudah tekan stop? Lotnya masih di dalam?","en":"Did you press stop first? Is the lot still inside?"},{"sp":"B","zh":"有，我按停了，裡面還有一批晶圓，目前看起來沒有破片。","py":"yǒu wǒ àn tíng le lǐ miàn hái yǒu yì pī jīng yuán mù qián kàn qǐ lái méi yǒu pò piàn","id":"Sudah, aku tekan stop. Di dalam masih ada satu lot wafer, sejauh ini kelihatannya tidak ada yang pecah.","en":"Yes, I stopped it. There's still a lot of wafers inside, and so far it looks like no broken wafers."},{"sp":"A","zh":"好，先不要重啟，也不要自己亂動，我馬上過去看。","py":"hǎo xiān bú yào chóng qǐ yě bú yào zì jǐ luàn dòng wǒ mǎ shàng guò qù kàn","id":"Oke, jangan di-restart dulu, jangan juga utak-atik sendiri, aku segera ke sana.","en":"OK, don't restart it yet and don't fiddle with it yourself. I'll be right over."},{"sp":"B","zh":"好。我先把警報畫面拍下來，等一下給你看。","py":"hǎo wǒ xiān bǎ jǐng bào huà miàn pāi xià lái děng yí xià gěi nǐ kàn","id":"Baik. Aku foto layar alarmnya dulu, nanti kutunjukkan.","en":"OK. I'll take a photo of the alarm screen first and show you in a moment."},{"sp":"A","zh":"對，順便把時間記下來，之前有沒有出現過類似的狀況？","py":"duì shùn biàn bǎ shí jiān jì xià lái zhī qián yǒu méi yǒu chū xiàn guò lèi sì de zhuàng kuàng","id":"Ya, sekalian catat waktunya. Sebelumnya pernah ada kejadian serupa?","en":"Yes, and note the time too. Has anything similar happened before?"},{"sp":"B","zh":"上禮拜好像有一次，但那時候重開機就好了。","py":"shàng lǐ bài hǎo xiàng yǒu yí cì dàn nà shí hòu chóng kāi jī jiù hǎo le","id":"Minggu lalu sepertinya pernah sekali, tapi waktu itu setelah di-restart langsung normal.","en":"I think once last week, but back then a restart fixed it."},{"sp":"A","zh":"那就怪了，可能是幫浦或是漏氣，我過去檢查一下。","py":"nà jiù guài le kě néng shì bāng pǔ huò shì lòu qì wǒ guò qù jiǎn chá yí xià","id":"Kalau begitu aneh. Mungkin pompa atau kebocoran, aku periksa dulu.","en":"Then that's strange. It could be the pump or a leak. I'll go check."},{"sp":"B","zh":"好，需要我在旁邊配合嗎？","py":"hǎo xū yào wǒ zài páng biān pèi hé ma","id":"Baik, perlu aku bantu di samping?","en":"OK, do you need me to assist?"},{"sp":"A","zh":"你先在這台掛上「維修中」的牌子，其他機台照常跑。","py":"nǐ xiān zài zhè tái guà shàng wéi xiū zhōng de pái zi qí tā jī tái zhào cháng pǎo","id":"Pasang dulu papan 「sedang diperbaiki」 di mesin ini, mesin lain jalan seperti biasa.","en":"Hang a \"Under Repair\" sign on this tool first; the other tools keep running as usual."}],"phrases":[{"zh":"機台跳警報了","py":"jī tái tiào jǐng bào le","id":"Mesin alarm"},{"zh":"腔體壓力降不下來","py":"qiāng tǐ yā lì jiàng bu xià lái","id":"Tekanan chamber tidak mau turun"},{"zh":"先不要自己亂動","py":"xiān bú yào zì jǐ luàn dòng","id":"Jangan utak-atik sendiri dulu"},{"zh":"我馬上過去看","py":"wǒ mǎ shàng guò qù kàn","id":"Aku segera ke sana melihat"},{"zh":"掛上維修中的牌子","py":"guà shàng wéi xiū zhōng de pái zi","id":"pasang papan sedang diperbaiki"}],"grammar":["ba","guo","le"],"task":{"id":"Ceritakan alarm yang terjadi pada sebuah mesin: kode/gejalanya, apa yang sudah kamu lakukan, dan apa yang kamu minta dari insinyur."}},{"id":"f_pm_planning","dom":"fab","lv":4,"title":{"zh":"與主管討論機台保養排程","id":"Membahas jadwal perawatan mesin dengan atasan","en":"Planning equipment PM with the supervisor"},"goal":{"id":"Setelah ini kamu bisa mendiskusikan dan menegosiasikan jadwal perawatan mesin dengan atasan."},"lines":[{"sp":"A","zh":"下個月的機台保養時程你排好了嗎？","py":"xià ge yuè de jī tái bǎo yǎng shí chéng nǐ pái hǎo le ma","id":"Jadwal perawatan mesin bulan depan sudah kamu susun?","en":"Have you finished scheduling next month's tool maintenance?"},{"sp":"B","zh":"排好了，我想把第二台和第五台的保養排在下週三。","py":"pái hǎo le wǒ xiǎng bǎ dì èr tái hé dì wǔ tái de bǎo yǎng pái zài xià zhōu sān","id":"Sudah, aku mau jadwalkan perawatan mesin kedua dan kelima hari Rabu depan.","en":"Done. I'd like to schedule tools two and five for maintenance next Wednesday."},{"sp":"A","zh":"下週三產線很滿，客戶的急件要出貨，可以往後延嗎？","py":"xià zhōu sān chǎn xiàn hěn mǎn kè hù de jí jiàn yào chū huò kě yǐ wǎng hòu yán ma","id":"Rabu depan lini produksi penuh, pesanan mendesak pelanggan harus dikirim, bisa diundur?","en":"Next Wednesday the line is packed and there's a rush order to ship. Can it be pushed back?"},{"sp":"B","zh":"這兩台的零件已經超過使用時數了，再拖下去怕會影響良率。","py":"zhè liǎng tái de líng jiàn yǐ jīng chāo guò shǐ yòng shí shù le zài tuō xià qù pà huì yǐng xiǎng liáng lǜ","id":"Komponen dua mesin ini sudah melewati jam pakainya, kalau terus ditunda dikhawatirkan memengaruhi yield.","en":"The parts on these two tools are past their service hours. If we drag it out, I'm afraid yield will suffer."},{"sp":"A","zh":"那你覺得最晚可以拖到什麼時候？","py":"nà nǐ jué de zuì wǎn kě yǐ tuō dào shén me shí hòu","id":"Menurutmu paling lambat bisa ditunda sampai kapan?","en":"So what's the latest you think we can wait?"},{"sp":"B","zh":"我評估過，最晚到下週五，不然腔體的粒子數可能會超標。","py":"wǒ píng gū guò zuì wǎn dào xià zhōu wǔ bù rán qiāng tǐ de lì zǐ shù kě néng huì chāo biāo","id":"Sudah kuperkirakan, paling lambat Jumat depan, kalau tidak jumlah partikel di chamber bisa melebihi batas.","en":"I've assessed it: Friday next week at the latest, otherwise the particle count in the chamber may go out of spec."},{"sp":"A","zh":"好，那就分兩天做，一天保養一台，產線不用同時停兩台。","py":"hǎo nà jiù fēn liǎng tiān zuò yì tiān bǎo yǎng yì tái chǎn xiàn bú yòng tóng shí tíng liǎng tái","id":"Oke, kalau begitu dibagi dua hari, sehari satu mesin, lini tidak perlu berhenti dua mesin sekaligus.","en":"OK, then split it over two days, one tool per day, so the line doesn't lose two tools at once."},{"sp":"B","zh":"可以，不過每台大概要停八個小時，要先跟生產部門講一聲。","py":"kě yǐ bú guò měi tái dà gài yào tíng bā ge xiǎo shí yào xiān gēn shēng chǎn bù mén jiǎng yì shēng","id":"Bisa, tapi setiap mesin harus berhenti sekitar delapan jam, harus kasih tahu bagian produksi dulu.","en":"Sure, but each tool will be down about eight hours, so we should tell the production department first."},{"sp":"A","zh":"這我來講。零件和耗材都備齊了嗎？","py":"zhè wǒ lái jiǎng líng jiàn hé hào cái dōu bèi qí le ma","id":"Itu aku yang bilang. Komponen dan bahan habis pakai sudah lengkap?","en":"I'll tell them. Are the parts and consumables all ready?"},{"sp":"B","zh":"墊片和濾網還沒到，我今天會跟倉庫確認。","py":"diàn piàn hé lǜ wǎng hái méi dào wǒ jīn tiān huì gēn cāng kù què rèn","id":"Gasket dan filter belum datang, hari ini aku konfirmasi ke gudang.","en":"The gaskets and filters haven't arrived. I'll confirm with the warehouse today."},{"sp":"A","zh":"好，如果零件沒到就要先告訴我，我們再調整日期。","py":"hǎo rú guǒ líng jiàn méi dào jiù yào xiān gào sù wǒ wǒ men zài tiáo zhěng rì qí","id":"Oke, kalau komponen belum datang kabari aku dulu, nanti kita sesuaikan tanggalnya.","en":"OK, if the parts don't arrive, tell me first and we'll adjust the dates."},{"sp":"B","zh":"沒問題，我確認完就更新保養計畫給你。","py":"méi wèn tí wǒ què rèn wán jiù gēng xīn bǎo yǎng jì huà gěi nǐ","id":"Tidak masalah, setelah konfirmasi aku perbarui rencana perawatan dan kirim ke Anda.","en":"No problem. Once I've confirmed, I'll send you the updated maintenance plan."}],"phrases":[{"zh":"可以往後延嗎","py":"kě yǐ wǎng hòu yán ma","id":"Bisakah diundur?"},{"zh":"再拖下去怕會影響良率","py":"zài tuō xià qù pà huì yǐng xiǎng liáng lǜ","id":"Kalau ditunda terus dikhawatirkan memengaruhi yield"},{"zh":"最晚可以拖到什麼時候","py":"zuì wǎn kě yǐ tuō dào shén me shí hòu","id":"Paling lambat bisa ditunda sampai kapan"},{"zh":"要先跟生產部門講一聲","py":"yào xiān gēn shēng chǎn bù mén jiǎng yì shēng","id":"Harus kasih tahu bagian produksi dulu"},{"zh":"我們再調整日期","py":"wǒ men zài tiáo zhěng rì qí","id":"Nanti kita sesuaikan tanggalnya"}],"grammar":["ba","guo","le"],"task":{"id":"Usulkan jadwal perawatan sebuah mesin kepada atasanmu, jelaskan alasannya, dan tawarkan alternatif tanggal."}},{"id":"f_yield_drop","dom":"fab","lv":5,"title":{"zh":"良率下降討論","id":"Diskusi penurunan yield","en":"Discussing a yield drop"},"goal":{"id":"Setelah ini kamu bisa mendiskusikan penyebab penurunan yield dan menentukan langkah pengecekan."},"lines":[{"sp":"A","zh":"這週的良率掉了快三個百分點，你有看到嗎？","py":"zhè zhōu de liáng lǜ diào le kuài sān ge bǎi fēn diǎn nǐ yǒu kàn dào ma","id":"Yield minggu ini turun hampir tiga poin persen, kamu sudah lihat?","en":"This week's yield dropped almost three percentage points. Have you seen it?"},{"sp":"B","zh":"有，我剛看完報表，主要是從週二開始掉的。","py":"yǒu wǒ gāng kàn wán bào biǎo zhǔ yào shì cóng zhōu èr kāi shǐ diào de","id":"Sudah, aku baru lihat laporannya, terutama mulai turun sejak hari Selasa.","en":"Yes, I just finished the report. It mostly started dropping on Tuesday."},{"sp":"A","zh":"週二那天有動過什麼嗎？換過耗材或是改過參數？","py":"zhōu èr nà tiān yǒu dòng guò shén me ma huàn guò hào cái huò shì gǎi guò cān shù","id":"Hari Selasa itu ada yang diubah? Ganti bahan habis pakai atau ubah parameter?","en":"Was anything touched that Tuesday? Consumables swapped or parameters changed?"},{"sp":"B","zh":"設備這邊只有做例行保養，沒有改參數。你那邊呢？","py":"shè bèi zhè biān zhǐ yǒu zuò lì xíng bǎo yǎng méi yǒu gǎi cān shù nǐ nà biān ne","id":"Di sisi peralatan hanya perawatan rutin, tidak ada parameter yang diubah. Di sisimu?","en":"On the equipment side we only did routine maintenance and changed no parameters. How about your side?"},{"sp":"A","zh":"我們也沒改。我先看一下缺陷分布，好像集中在晶圓邊緣。","py":"wǒ men yě méi gǎi wǒ xiān kàn yí xià quē xiàn fēn bù hǎo xiàng jí zhōng zài jīng yuán biān yuán","id":"Kami juga tidak mengubah. Aku lihat sebaran cacat dulu, sepertinya terkonsentrasi di tepi wafer.","en":"We didn't change anything either. Let me look at the defect map first. It seems concentrated at the wafer edge."},{"sp":"B","zh":"邊緣？那有可能跟腔體有關，會不會是保養完以後沒有調好？","py":"biān yuán nà yǒu kě néng gēn qiāng tǐ yǒu guān huì bú huì shì bǎo yǎng wán yǐ hòu méi yǒu tiáo hǎo","id":"Tepi? Mungkin berkaitan dengan chamber, jangan-jangan setelah perawatan belum disetel dengan benar?","en":"The edge? That could be related to the chamber. Could it be it wasn't tuned right after maintenance?"},{"sp":"A","zh":"有可能。是哪幾台機台的貨比較差？","py":"yǒu kě néng shì nǎ jǐ tái jī tái de huò bǐ jiào chà","id":"Mungkin. Lot dari mesin mana saja yang lebih buruk?","en":"Possible. Which tools' lots are worse?"},{"sp":"B","zh":"我查一下，都是同一台蝕刻機跑出來的。","py":"wǒ chá yí xià dōu shì tóng yì tái shí kè jī pǎo chū lái de","id":"Aku cek dulu, semuanya dari mesin etching yang sama.","en":"Let me check. They all came out of the same etcher."},{"sp":"A","zh":"那就先把那台停下來，不要再跑貨，不然會繼續出問題。","py":"nà jiù xiān bǎ nà tái tíng xià lái bú yào zài pǎo huò bù rán huì jì xù chū wèn tí","id":"Kalau begitu hentikan mesin itu dulu, jangan jalankan lot lagi, kalau tidak masalahnya akan berlanjut.","en":"Then stop that tool first and don't run any more lots, or the problem will continue."},{"sp":"B","zh":"好，我現在就去量一下腔體的狀態，再用測試片跑一次。","py":"hǎo wǒ xiàn zài jiù qù liáng yí xià qiāng tǐ de zhuàng tài zài yòng cè shì piàn pǎo yí cì","id":"Baik, aku sekarang ukur kondisi chamber, lalu jalankan sekali lagi dengan wafer uji.","en":"OK, I'll go measure the chamber condition now and then run a test wafer."},{"sp":"A","zh":"結果出來再跟我說，我下午要跟客戶報告。","py":"jié guǒ chū lái zài gēn wǒ shuō wǒ xià wǔ yào gēn kè hù bào gào","id":"Kabari aku setelah hasilnya keluar, sore ini aku harus lapor ke pelanggan.","en":"Tell me once you have results. I have to report to the customer this afternoon."},{"sp":"B","zh":"好，一個小時內我會給你初步的答案。","py":"hǎo yí ge xiǎo shí nèi wǒ huì gěi nǐ chū bù de dá àn","id":"Baik, dalam satu jam aku beri jawaban awal.","en":"OK, I'll give you a preliminary answer within an hour."}],"phrases":[{"zh":"良率掉了快三個百分點","py":"liáng lǜ diào le kuài sān ge bǎi fēn diǎn","id":"Yield turun hampir tiga persen"},{"zh":"週二那天有動過什麼嗎","py":"zhōu èr nà tiān yǒu dòng guò shén me ma","id":"Hari Selasa itu ada yang diubah/disentuh?"},{"zh":"集中在晶圓邊緣","py":"jí zhōng zài jīng yuán biān yuán","id":"Terkonsentrasi di tepi wafer"},{"zh":"會不會是保養完以後沒有調好","py":"huì bú huì shì bǎo yǎng wán yǐ hòu méi yǒu tiáo hǎo","id":"Jangan-jangan setelah perawatan belum disetel dengan benar"},{"zh":"先把那台停下來","py":"xiān bǎ nà tái tíng xià lái","id":"hentikan mesin itu dulu"}],"grammar":["guo","bu","ba"],"task":{"id":"Kamu melihat yield turun. Diskusikan dengan rekan: kapan mulai turun, apa yang berubah, dan apa yang akan kamu cek lebih dulu."}},{"id":"f_lot_hold_system","dom":"fab","lv":4,"title":{"zh":"貨被卡住與查詢系統","id":"Lot tertahan dan cek sistem","en":"A lot on hold and checking the system"},"goal":{"id":"Setelah ini kamu bisa menanyakan penyebab lot tertahan dan mencari informasinya di sistem."},"lines":[{"sp":"B","zh":"學姐，這一批貨我出不了站，系統顯示被卡住了。","py":"xué jiě zhè yì pī huò wǒ chū bù liǎo zhàn xì tǒng xiǎn shì bèi qiǎ zhù le","id":"Kak, lot ini tidak bisa aku track-out, sistem menunjukkan tertahan.","en":"Senior, I can't check out this lot. The system says it's on hold."},{"sp":"A","zh":"我看一下。你點進批號資料，看一下卡貨的原因。","py":"wǒ kàn yí xià nǐ diǎn jìn pī hào zī liào kàn yí xià qiǎ huò de yuán yīn","id":"Aku lihat dulu. Klik masuk data nomor lot, lihat alasan lot ditahan.","en":"Let me see. Open the lot data and check why it's held."},{"sp":"B","zh":"寫的是「膜厚量測超出規格」，是誰卡的？","py":"xiě de shì mó hòu liáng cè chāo chū guī gé shì shéi qiǎ de","id":"Tertulis 「pengukuran ketebalan film melebihi spesifikasi」, siapa yang menahan?","en":"It says 'film thickness measurement out of spec'. Who put the hold?"},{"sp":"A","zh":"上面寫是品管卡的，你不能自己解除，要等他們處理。","py":"shàng miàn xiě shì pǐn guǎn qiǎ de nǐ bù néng zì jǐ jiě chú yào děng tā men chǔ lǐ","id":"Di situ tertulis ditahan oleh QC, kamu tidak boleh melepasnya sendiri, harus tunggu mereka menangani.","en":"It says QC put it on hold. You can't release it yourself, you have to wait for them."},{"sp":"B","zh":"那我要打電話給他們嗎？貨放在這裡會不會有問題？","py":"nà wǒ yào dǎ diàn huà gěi tā men ma huò fàng zài zhè lǐ huì bú huì yǒu wèn tí","id":"Jadi aku perlu menelepon mereka? Lot ditaruh di sini apa tidak masalah?","en":"Should I call them? Is it a problem to leave the lot here?"},{"sp":"A","zh":"先打給品管，問一下預計什麼時候會處理。另外，這批光阻塗佈完有時間限制，要特別注意。","py":"xiān dǎ gěi pǐn guǎn wèn yí xià yù jì shén me shí hòu huì chǔ lǐ lìng wài zhè pī guāng zǔ tú bù wán yǒu shí jiān xiàn zhì yào tè bié zhù yì","id":"Telepon QC dulu, tanya kira-kira kapan ditangani. Selain itu, lot ini setelah coating photoresist punya batas waktu, harus diperhatikan.","en":"Call QC first and ask when they expect to handle it. Also, after resist coating this lot has a time limit, so watch out."},{"sp":"B","zh":"時間限制是幾個小時？我在系統哪裡可以查到？","py":"shí jiān xiàn zhì shì jǐ ge xiǎo shí wǒ zài xì tǒng nǎ lǐ kě yǐ chá dào","id":"Batas waktunya berapa jam? Di mana aku bisa melihatnya di sistem?","en":"How many hours is the time limit? Where can I find it in the system?"},{"sp":"A","zh":"在製程條件那一頁，有一欄是等待時間上限，你看，這批只剩四個小時。","py":"zài zhì chéng tiáo jiàn nà yí yè yǒu yì lán shì děng dài shí jiān shàng xiàn nǐ kàn zhè pī zhǐ shèng sì ge xiǎo shí","id":"Di halaman kondisi proses, ada satu kolom batas waktu tunggu. Lihat, lot ini tinggal empat jam.","en":"On the process conditions page there's a column for maximum wait time. See, this lot has only four hours left."},{"sp":"B","zh":"了解，我先打電話給品管，再把結果記在系統裡。","py":"liǎo jiě wǒ xiān dǎ diàn huà gěi pǐn guǎn zài bǎ jié guǒ jì zài xì tǒng lǐ","id":"Mengerti, aku telepon QC dulu, lalu catat hasilnya di sistem.","en":"Got it. I'll call QC first and then record the result in the system."},{"sp":"A","zh":"對，如果超過時間，就要通知工程師決定要不要重工。","py":"duì rú guǒ chāo guò shí jiān jiù yào tōng zhī gōng chéng shī jué dìng yào bú yào chóng gōng","id":"Ya, kalau lewat batas waktu, harus beri tahu insinyur untuk memutuskan perlu rework atau tidak.","en":"Right. If it goes past the limit, notify the engineer to decide whether to rework."},{"sp":"B","zh":"好，我知道了，謝謝學姐。","py":"hǎo wǒ zhī dào le xiè xie xué jiě","id":"Baik, aku mengerti, terima kasih Kak.","en":"OK, understood. Thanks, senior."}],"phrases":[{"zh":"系統顯示被卡住了","py":"xì tǒng xiǎn shì bèi qiǎ zhù le","id":"Sistem menunjukkan lot tertahan"},{"zh":"你不能自己解除","py":"nǐ bù néng zì jǐ jiě chú","id":"Kamu tidak boleh melepasnya sendiri"},{"zh":"問一下預計什麼時候會處理","py":"wèn yí xià yù jì shén me shí hòu huì chǔ lǐ","id":"Tanya kira-kira kapan akan ditangani"},{"zh":"在系統哪裡可以查到","py":"zài xì tǒng nǎ lǐ kě yǐ chá dào","id":"Di mana bisa dicek di sistem"},{"zh":"要不要重工","py":"yào bú yào chóng gōng","id":"Perlu rework atau tidak"}],"grammar":["bei","ba","aux"],"task":{"id":"Kamu menemukan sebuah lot tertahan. Ceritakan apa yang kamu lihat di sistem dan siapa yang akan kamu hubungi."}},{"id":"f_recipe_adjust_senior","dom":"fab","lv":5,"title":{"zh":"請教學長如何安全調整配方","id":"Bertanya ke senior cara aman mengubah recipe","en":"Asking a senior how to adjust a recipe safely"},"goal":{"id":"Setelah ini kamu bisa menanyakan prosedur aman untuk mengubah recipe atau parameter mesin."},"lines":[{"sp":"B","zh":"學長，我想請教你一個問題，如果要微調配方裡的溫度，要怎麼做才安全？","py":"xué zhǎng wǒ xiǎng qǐng jiào nǐ yí ge wèn tí rú guǒ yào wéi tiáo pèi fāng lǐ de wēn dù yào zěn me zuò cái ān quán","id":"Kak, aku mau tanya, kalau mau menyetel sedikit suhu di recipe, bagaimana caranya supaya aman?","en":"Senior, I have a question. If I want to fine-tune the temperature in a recipe, how do I do it safely?"},{"sp":"A","zh":"你先講，是哪一台機台？要調多少？","py":"nǐ xiān jiǎng shì nǎ yì tái jī tái yào tiáo duō shǎo","id":"Ceritakan dulu, mesin yang mana? Mau disetel berapa?","en":"Tell me first. Which tool? How much do you want to change?"},{"sp":"B","zh":"擴散爐，我想把溫度調高五度，讓氧化層長厚一點。","py":"kuò sàn lú wǒ xiǎng bǎ wēn dù tiáo gāo wǔ dù ràng yǎng huà céng zhǎng hòu yì diǎn","id":"Tungku difusi. Aku mau menaikkan suhu lima derajat supaya lapisan oksidanya tumbuh lebih tebal.","en":"The diffusion furnace. I want to raise the temperature by five degrees so the oxide grows a bit thicker."},{"sp":"A","zh":"先停一下，千萬不要直接改正式的配方。你有沒有看過變更管理的規定？","py":"xiān tíng yí xià qiān wàn bú yào zhí jiē gǎi zhèng shì de pèi fāng nǐ yǒu méi yǒu kàn guò biàn gēng guǎn lǐ de guī dìng","id":"Berhenti dulu, jangan sekali-kali langsung mengubah recipe resmi. Sudah baca aturan manajemen perubahan?","en":"Hold on, never edit the production recipe directly. Have you read the change management rules?"},{"sp":"B","zh":"還沒有，是要先填單子嗎？","py":"hái méi yǒu shì yào xiān tián dān zi ma","id":"Belum, apakah harus isi formulir dulu?","en":"Not yet. Do I have to fill out a form first?"},{"sp":"A","zh":"對，要先填變更申請，讓製程工程師和主管簽核，通過之後才可以動。","py":"duì yào xiān tián biàn gēng shēn qǐng ràng zhì chéng gōng chéng shī hé zhǔ guǎn qiān hé tōng guò zhī hòu cái kě yǐ dòng","id":"Ya, isi pengajuan perubahan dulu, minta insinyur proses dan atasan menyetujui, baru boleh diubah setelah disetujui.","en":"Yes. Fill out a change request, get the process engineer and supervisor to sign off, and only then can you touch it."},{"sp":"B","zh":"那在簽核之前，我要怎麼先驗證這個溫度可不可行？","py":"nà zài qiān hé zhī qián wǒ yào zěn me xiān yàn zhèng zhè ge wēn dù kě bù kě xíng","id":"Lalu sebelum disetujui, bagaimana aku memverifikasi dulu apakah suhu ini layak?","en":"Then before sign-off, how can I first verify whether this temperature works?"},{"sp":"A","zh":"你可以複製一份配方當作工程版，用測試片先跑，不要用正式的貨。","py":"nǐ kě yǐ fù zhì yí fèn pèi fāng dàng zuò gōng chéng bǎn yòng cè shì piàn xiān pǎo bú yào yòng zhèng shì de huò","id":"Kamu bisa menyalin recipe sebagai versi engineering dan jalankan dengan wafer uji, jangan pakai lot produksi.","en":"You can copy the recipe as an engineering version and run test wafers first, not production lots."},{"sp":"B","zh":"原來如此，那我改完以後要記錄什麼？","py":"yuán lái rú cǐ nà wǒ gǎi wán yǐ hòu yào jì lù shén me","id":"Oh begitu, lalu setelah mengubah aku harus mencatat apa?","en":"I see. So what do I need to record after changing it?"},{"sp":"A","zh":"改了什麼、為什麼改、測試結果，這三個都要寫清楚，以後才查得到。","py":"gǎi le shén me wèi shén me gǎi cè shì jié guǒ zhè sān ge dōu yào xiě qīng chǔ yǐ hòu cái chá de dào","id":"Apa yang diubah, kenapa diubah, dan hasil uji, ketiganya harus ditulis jelas supaya nanti bisa dilacak.","en":"What you changed, why, and the test result. Write all three clearly so it can be traced later."},{"sp":"B","zh":"好，我先把變更申請寫好，再來找你確認。","py":"hǎo wǒ xiān bǎ biàn gēng shēn qǐng xiě hǎo zài lái zhǎo nǐ què rèn","id":"Baik, aku tulis dulu pengajuan perubahannya, lalu datang ke Kakak untuk konfirmasi.","en":"OK, I'll write up the change request first and then come to you to confirm."},{"sp":"A","zh":"沒問題，寫完傳給我，我先幫你看一下。","py":"méi wèn tí xiě wán chuán gěi wǒ wǒ xiān bāng nǐ kàn yí xià","id":"Tidak masalah, setelah selesai kirim ke aku, aku bantu lihat dulu.","en":"No problem. Send it to me when it's done and I'll take a look first."}],"phrases":[{"zh":"要怎麼做才安全","py":"yào zěn me zuò cái ān quán","id":"Bagaimana caranya supaya aman"},{"zh":"千萬不要直接改正式的配方","py":"qiān wàn bú yào zhí jiē gǎi zhèng shì de pèi fāng","id":"Jangan sekali-kali langsung mengubah recipe resmi"},{"zh":"要先填變更申請","py":"yào xiān tián biàn gēng shēn qǐng","id":"Harus isi pengajuan perubahan dulu"},{"zh":"用測試片先跑","py":"yòng cè shì piàn xiān pǎo","id":"Jalankan dulu dengan wafer uji"},{"zh":"寫完傳給我","py":"xiě wán chuán gěi wǒ","id":"Kirim ke aku setelah selesai ditulis"}],"grammar":["ba","aux","bu"],"task":{"id":"Kamu ingin mengubah satu parameter mesin. Tanyakan kepada seniormu langkah-langkah aman sebelum mengubahnya."}},{"id":"f_near_miss_report","dom":"fab","lv":5,"title":{"zh":"化學品與氣體虛驚事件通報","id":"Laporan nyaris celaka bahan kimia/gas","en":"Reporting a chemical or gas near-miss"},"goal":{"id":"Setelah ini kamu bisa melaporkan kejadian nyaris celaka (near-miss) bahan kimia atau gas dengan jelas."},"lines":[{"sp":"B","zh":"不好意思，我想報告一件今天早上發生的虛驚事件。","py":"bù hǎo yì si wǒ xiǎng bào gào yí jiàn jīn tiān zǎo shàng fā shēng de xū jīng shì jiàn","id":"Maaf, aku mau melaporkan kejadian nyaris celaka tadi pagi.","en":"Excuse me, I'd like to report a near-miss incident from this morning."},{"sp":"A","zh":"好，你慢慢說，有沒有人受傷？","py":"hǎo nǐ màn màn shuō yǒu méi yǒu rén shòu shāng","id":"Baik, pelan-pelan saja, ada yang terluka?","en":"OK, take your time. Was anyone hurt?"},{"sp":"B","zh":"沒有人受傷。我在換藥液桶的時候，聞到一點酸味，氣體偵測器還響了一下。","py":"méi yǒu rén shòu shāng wǒ zài huàn yào yì tǒng de shí hòu wén dào yì diǎn suān wèi qì tǐ zhēn cè qì hái xiǎng le yí xià","id":"Tidak ada yang terluka. Saat aku mengganti drum cairan kimia, tercium sedikit bau asam, detektor gas juga sempat berbunyi.","en":"Nobody was hurt. While I was changing a chemical drum I smelled a bit of acid, and the gas detector also beeped once."},{"sp":"A","zh":"酸味？你當時有戴防護面罩和手套嗎？","py":"suān wèi nǐ dāng shí yǒu dài fáng hù miàn zhào hé shǒu tào ma","id":"Bau asam? Waktu itu kamu pakai pelindung wajah dan sarung tangan?","en":"An acid smell? Were you wearing a face shield and gloves?"},{"sp":"B","zh":"有，我有戴，可是管線接頭的地方好像有一點點滲漏。","py":"yǒu wǒ yǒu dài kě shì guǎn xiàn jiē tóu de dì fāng hǎo xiàng yǒu yì diǎn diǎn shèn lòu","id":"Ya, aku pakai, tapi sambungan pipanya sepertinya ada rembesan sedikit.","en":"Yes, I was, but the pipe fitting seemed to have a tiny leak."},{"sp":"A","zh":"你有立刻停止作業，通知現場的人撤離嗎？","py":"nǐ yǒu lì kè tíng zhǐ zuò yè tōng zhī xiàn chǎng de rén chè lí ma","id":"Kamu langsung menghentikan pekerjaan dan memberi tahu orang di lokasi untuk evakuasi?","en":"Did you stop work immediately and tell people on site to evacuate?"},{"sp":"B","zh":"有，我先關掉閥門，然後按下緊急通報，同事也先離開那個區域。","py":"yǒu wǒ xiān guān diào fá mén rán hòu àn xià jǐn jí tōng bào tóng shì yě xiān lí kāi nà ge qū yù","id":"Ya, aku menutup katup dulu, lalu menekan tombol laporan darurat, rekan-rekan juga keluar dari area itu.","en":"Yes, I closed the valve first, then hit the emergency alert, and my coworkers left the area too."},{"sp":"A","zh":"做得很好。後來有人去處理嗎？","py":"zuò de hěn hǎo hòu lái yǒu rén qù chǔ lǐ ma","id":"Bagus sekali. Setelah itu ada yang menangani?","en":"Well done. Did someone handle it afterwards?"},{"sp":"B","zh":"有，設備工程師換了接頭，已經沒有味道了，偵測器也恢復正常。","py":"yǒu shè bèi gōng chéng shī huàn le jiē tóu yǐ jīng méi yǒu wèi dào le zhēn cè qì yě huī fù zhèng cháng","id":"Ya, insinyur peralatan mengganti sambungannya, sudah tidak ada bau, detektor juga kembali normal.","en":"Yes, the equipment engineer replaced the fitting. The smell is gone and the detector is back to normal."},{"sp":"A","zh":"好，我現在幫你填虛驚事件報告，請你把時間和地點說清楚。","py":"hǎo wǒ xiàn zài bāng nǐ tián xū jīng shì jiàn bào gào qǐng nǐ bǎ shí jiān hé dì diǎn shuō qīng chǔ","id":"Baik, sekarang aku bantu isi laporan nyaris celaka, tolong jelaskan waktu dan lokasinya dengan jelas.","en":"OK, I'll fill in the near-miss report for you now. Please state the time and place clearly."},{"sp":"B","zh":"大約八點四十分，在三樓的濕式清洗區，第二號藥液櫃旁邊。","py":"dà yuē bā diǎn sì shí fēn zài sān lóu de shī shì qīng xǐ qū dì èr hào yào yì guì páng biān","id":"Sekitar pukul delapan empat puluh, di area wet cleaning lantai tiga, di samping lemari bahan kimia nomor dua.","en":"Around 8:40, in the wet cleaning area on the third floor, next to chemical cabinet number two."},{"sp":"A","zh":"謝謝你主動通報，這樣我們才能改善，避免下次真的有人受傷。","py":"xiè xie nǐ zhǔ dòng tōng bào zhè yàng wǒ men cái néng gǎi shàn bì miǎn xià cì zhēn de yǒu rén shòu shāng","id":"Terima kasih sudah melapor secara proaktif, dengan begitu kami bisa memperbaiki dan mencegah ada yang benar-benar terluka lain kali.","en":"Thanks for reporting proactively. That way we can improve and avoid someone really getting hurt next time."}],"phrases":[{"zh":"我想報告一件虛驚事件","py":"wǒ xiǎng bào gào yí jiàn xū jīng shì jiàn","id":"Aku mau melaporkan kejadian nyaris celaka"},{"zh":"氣體偵測器響了一下","py":"qì tǐ zhēn cè qì xiǎng le yí xià","id":"Detektor gas sempat berbunyi"},{"zh":"我先關掉閥門","py":"wǒ xiān guān diào fá mén","id":"Aku menutup katup dulu"},{"zh":"按下緊急通報","py":"àn xià jǐn jí tōng bào","id":"Menekan laporan darurat"},{"zh":"把時間和地點說清楚","py":"bǎ shí jiān hé dì diǎn shuō qīng chǔ","id":"Menyebutkan waktu dan lokasi dengan jelas"}],"grammar":["ba","le","guo"],"task":{"id":"Laporkan sebuah kejadian nyaris celaka: apa yang kamu cium/lihat, apa yang kamu lakukan, dan di mana serta kapan terjadinya."}},{"id":"f_spare_parts_request","dom":"fab","lv":4,"title":{"zh":"向倉庫申請備品","id":"Meminta suku cadang dari gudang","en":"Requesting spare parts from the warehouse"},"goal":{"id":"Setelah ini kamu bisa meminta suku cadang ke gudang dan mengurus formulir yang diperlukan."},"lines":[{"sp":"B","zh":"你好，我想領一個真空幫浦的濾網，請問倉庫有庫存嗎？","py":"nǐ hǎo wǒ xiǎng lǐng yí ge zhēn kōng bāng pǔ de lǜ wǎng qǐng wèn cāng kù yǒu kù cún ma","id":"Halo, aku mau mengambil satu filter pompa vakum, apakah gudang ada stok?","en":"Hello, I'd like to pick up a filter for a vacuum pump. Is there stock in the warehouse?"},{"sp":"A","zh":"你有料號嗎？我幫你查一下系統。","py":"nǐ yǒu liào hào ma wǒ bāng nǐ chá yí xià xì tǒng","id":"Kamu punya nomor material? Aku bantu cek sistem.","en":"Do you have the part number? I'll check the system for you."},{"sp":"B","zh":"有，料號寫在這張單子上，是五號機要用的。","py":"yǒu liào hào xiě zài zhè zhāng dān zi shàng shì wǔ hào jī yào yòng de","id":"Ada, nomornya tertulis di formulir ini, untuk mesin nomor lima.","en":"Yes, the part number is on this form. It's for tool No. 5."},{"sp":"A","zh":"我看一下，系統顯示只剩一個，放在二樓的備品倉庫。","py":"wǒ kàn yí xià xì tǒng xiǎn shì zhǐ shèng yí ge fàng zài èr lóu de bèi pǐn cāng kù","id":"Aku lihat dulu, sistem menunjukkan tinggal satu, disimpan di gudang suku cadang lantai dua.","en":"Let me see. The system shows only one left, in the spare parts warehouse on the second floor."},{"sp":"B","zh":"那我可以現在領嗎？我今天下午就要換。","py":"nà wǒ kě yǐ xiàn zài lǐng ma wǒ jīn tiān xià wǔ jiù yào huàn","id":"Kalau begitu boleh aku ambil sekarang? Sore ini aku harus menggantinya.","en":"Can I take it now, then? I need to replace it this afternoon."},{"sp":"A","zh":"可以，不過你要先在系統上開領料單，主管簽核以後我才能發料。","py":"kě yǐ bú guò nǐ yào xiān zài xì tǒng shàng kāi lǐng liào dān zhǔ guǎn qiān hé yǐ hòu wǒ cái néng fā liào","id":"Bisa, tapi kamu harus buat surat pengambilan material di sistem dulu, setelah atasan menyetujui baru aku bisa mengeluarkan barang.","en":"Yes, but first create a material requisition in the system. I can only issue it after your supervisor signs off."},{"sp":"B","zh":"已經開好了，主管剛剛簽完，你再看一下。","py":"yǐ jīng kāi hǎo le zhǔ guǎn gāng gāng qiān wán nǐ zài kàn yí xià","id":"Sudah dibuat, atasan baru saja menyetujui, coba cek lagi.","en":"It's done. My supervisor just signed it. Please check again."},{"sp":"A","zh":"對，有了。不過你領走以後就沒庫存了，要趕快補貨。","py":"duì yǒu le bú guò nǐ lǐng zǒu yǐ hòu jiù méi kù cún le yào gǎn kuài bǔ huò","id":"Ya, sudah ada. Tapi setelah kamu ambil stoknya habis, harus segera restok.","en":"Yes, it's there. But once you take it, we're out of stock, so it needs restocking soon."},{"sp":"B","zh":"對，那我順便申請再訂兩個備用，以免下次又沒料。","py":"duì nà wǒ shùn biàn shēn qǐng zài dìng liǎng ge bèi yòng yǐ miǎn xià cì yòu méi liào","id":"Ya, kalau begitu sekalian aku ajukan pesan dua lagi untuk cadangan, supaya lain kali tidak kehabisan lagi.","en":"Right, so I'll also request two more as backups so we don't run out again next time."},{"sp":"A","zh":"好，你填請購單，交期大概要三個禮拜，因為是進口的。","py":"hǎo nǐ tián qǐng gòu dān jiāo qí dà gài yào sān ge lǐ bài yīn wèi shì jìn kǒu de","id":"Baik, isi formulir permintaan pembelian, waktu pengiriman sekitar tiga minggu karena barang impor.","en":"OK, fill out a purchase request. Lead time is about three weeks since it's imported."},{"sp":"B","zh":"三個禮拜喔，那我跟主管說，把安全庫存提高到兩個。","py":"sān ge lǐ bài o nà wǒ gēn zhǔ guǎn shuō bǎ ān quán kù cún tí gāo dào liǎng ge","id":"Tiga minggu ya, kalau begitu aku bilang ke atasan untuk menaikkan stok pengaman jadi dua.","en":"Three weeks, huh. Then I'll ask my supervisor to raise the safety stock to two."},{"sp":"A","zh":"可以。來，這是你的濾網，請在這裡簽名，舊的要記得拿回來報廢。","py":"kě yǐ lái zhè shì nǐ de lǜ wǎng qǐng zài zhè lǐ qiān míng jiù de yào jì de ná huí lái bào fèi","id":"Boleh. Ini filtermu, tolong tanda tangan di sini, yang lama jangan lupa dibawa kembali untuk dihapuskan.","en":"OK. Here's your filter. Please sign here, and remember to bring the old one back for scrapping."},{"sp":"B","zh":"好，謝謝，舊的我換完就拿回來。","py":"hǎo xiè xie jiù de wǒ huàn wán jiù ná huí lái","id":"Baik, terima kasih, yang lama setelah kuganti akan kubawa kembali.","en":"OK, thanks. I'll bring the old one back once I've swapped it."}],"phrases":[{"zh":"請問倉庫有庫存嗎","py":"qǐng wèn cāng kù yǒu kù cún ma","id":"Permisi, apakah gudang ada stok?"},{"zh":"你有料號嗎","py":"nǐ yǒu liào hào ma","id":"Kamu punya nomor material?"},{"zh":"要先開領料單","py":"yào xiān kāi lǐng liào dān","id":"Harus buat surat pengambilan material dulu"},{"zh":"以免下次又沒料","py":"yǐ miǎn xià cì yòu méi liào","id":"Supaya lain kali tidak kehabisan lagi"},{"zh":"舊的要拿回來報廢","py":"jiù de yào ná huí lái bào fèi","id":"Yang lama harus dibawa kembali untuk dihapuskan"}],"grammar":["ba","aux","yinwei"],"task":{"id":"Minta satu suku cadang ke gudang: sebutkan nomor material, untuk mesin mana, kapan dibutuhkan, dan apa yang perlu diurus."}},{"id":"f_downtime_explain","dom":"fab","lv":5,"title":{"zh":"向生產部門說明停機原因","id":"Menjelaskan penyebab downtime ke tim produksi","en":"Explaining downtime to the production team"},"goal":{"id":"Setelah ini kamu bisa menjelaskan penyebab dan estimasi pemulihan mesin kepada tim produksi serta menawarkan solusi."},"lines":[{"sp":"A","zh":"工程師，那台機台已經停了兩個小時，什麼時候可以跑貨？","py":"gōng chéng shī nà tái jī tái yǐ jīng tíng le liǎng ge xiǎo shí shén me shí hòu kě yǐ pǎo huò","id":"Pak insinyur, mesin itu sudah berhenti dua jam, kapan bisa jalan lagi?","en":"Engineer, that tool has been down for two hours. When can it run lots again?"},{"sp":"B","zh":"不好意思讓你們等這麼久。目前原因找到了，是加熱器壞掉了。","py":"bù hǎo yì si ràng nǐ men děng zhè me jiǔ mù qián yuán yīn zhǎo dào le shì jiā rè qì huài diào le","id":"Maaf membuat kalian menunggu lama. Penyebabnya sudah ketemu, pemanasnya rusak.","en":"Sorry to keep you waiting so long. We've found the cause: the heater is broken."},{"sp":"A","zh":"要換很久嗎？我們線上有一批急件要趕出貨。","py":"yào huàn hěn jiǔ ma wǒ men xiàn shàng yǒu yì pī jí jiàn yào gǎn chū huò","id":"Penggantiannya lama? Di lini kami ada satu lot mendesak yang harus segera dikirim.","en":"Will the replacement take long? We have a rush lot on the line that has to ship."},{"sp":"B","zh":"零件倉庫有現貨，換完大概要一個半小時，再加上測試，預計下午三點可以恢復。","py":"líng jiàn cāng kù yǒu xiàn huò huàn wán dà gài yào yí ge bàn xiǎo shí zài jiā shàng cè shì yù jì xià wǔ sān diǎn kě yǐ huī fù","id":"Gudang suku cadang ada stok, penggantian sekitar satu setengah jam, ditambah pengujian, diperkirakan pulih jam tiga sore.","en":"The warehouse has the part in stock. Replacement takes about an hour and a half, plus testing, so we expect recovery at 3 p.m."},{"sp":"A","zh":"三點？那太晚了，客戶明天早上就要貨。","py":"sān diǎn nà tài wǎn le kè hù míng tiān zǎo shàng jiù yào huò","id":"Jam tiga? Itu terlalu lambat, pelanggan butuh barangnya besok pagi.","en":"Three o'clock? That's too late. The customer needs the goods tomorrow morning."},{"sp":"B","zh":"我了解，所以我建議把急件先移到隔壁的同型機台跑，那台今天沒有排貨。","py":"wǒ liǎo jiě suǒ yǐ wǒ jiàn yì bǎ jí jiàn xiān yí dào gé bì de tóng xíng jī tái pǎo nà tái jīn tiān méi yǒu pái huò","id":"Aku mengerti, jadi kusarankan lot mendesak dipindah dulu ke mesin sejenis di sebelah, mesin itu hari ini tidak dijadwalkan lot.","en":"I understand, so I suggest moving the rush lot to the identical tool next door, which has nothing scheduled today."},{"sp":"A","zh":"可以嗎？兩台機台的條件一樣嗎？","py":"kě yǐ ma liǎng tái jī tái de tiáo jiàn yí yàng ma","id":"Boleh? Kondisi kedua mesin sama?","en":"Is that OK? Are the conditions on the two tools the same?"},{"sp":"B","zh":"我剛確認過，參數都一樣，只要先用測試片驗證一下，沒問題就可以放貨。","py":"wǒ gāng què rèn guò cān shù dōu yí yàng zhǐ yào xiān yòng cè shì piàn yàn zhèng yí xià méi wèn tí jiù kě yǐ fàng huò","id":"Barusan aku konfirmasi, parameternya sama semua, tinggal verifikasi dengan wafer uji, kalau tidak ada masalah lot bisa dimasukkan.","en":"I just confirmed that the parameters are all the same. We only need to verify with a test wafer first, and if it's fine we can load the lot."},{"sp":"A","zh":"好，那我請同仁先準備，你什麼時候可以給我結果？","py":"hǎo nà wǒ qǐng tóng rén xiān zhǔn bèi nǐ shén me shí hòu kě yǐ gěi wǒ jié guǒ","id":"Baik, aku minta rekan-rekan bersiap dulu, kapan kamu bisa beri hasilnya?","en":"OK, I'll have my people get ready. When can you give me the result?"},{"sp":"B","zh":"三十分鐘內，我驗證完就馬上打給你。","py":"sān shí fēn zhōng nèi wǒ yàn zhèng wán jiù mǎ shàng dǎ gěi nǐ","id":"Dalam tiga puluh menit, begitu selesai verifikasi aku langsung telepon.","en":"Within thirty minutes. As soon as I finish verifying I'll call you."},{"sp":"A","zh":"好，麻煩你了。那這次停機的原因，之後會不會再發生？","py":"hǎo má fán nǐ le nà zhè cì tíng jī de yuán yīn zhī hòu huì bú huì zài fā shēng","id":"Baik, merepotkanmu. Lalu penyebab berhenti kali ini, apakah akan terjadi lagi?","en":"OK, thanks for the trouble. And will the cause of this stoppage happen again?"},{"sp":"B","zh":"這種加熱器已經用很久了，我會把其他幾台也一起檢查，避免再發生。","py":"zhè zhǒng jiā rè qì yǐ jīng yòng hěn jiǔ le wǒ huì bǎ qí tā jǐ tái yě yì qǐ jiǎn chá bì miǎn zài fā shēng","id":"Pemanas jenis ini sudah dipakai lama, aku akan periksa beberapa mesin lain sekalian untuk mencegahnya terulang.","en":"This type of heater has been in use for a long time. I'll check the other tools together to prevent a repeat."}],"phrases":[{"zh":"不好意思讓你們等這麼久","py":"bù hǎo yì si ràng nǐ men děng zhè me jiǔ","id":"Maaf membuat kalian menunggu selama ini"},{"zh":"預計下午三點可以恢復","py":"yù jì xià wǔ sān diǎn kě yǐ huī fù","id":"Diperkirakan pulih jam tiga sore"},{"zh":"我建議把急件先移到隔壁的機台跑","py":"wǒ jiàn yì bǎ jí jiàn xiān yí dào gé bì de jī tái pǎo","id":"Kusarankan lot mendesak dipindah ke mesin sebelah"},{"zh":"沒問題就可以放貨","py":"méi wèn tí jiù kě yǐ fàng huò","id":"Kalau tidak ada masalah lot bisa dimasukkan"},{"zh":"我驗證完就馬上打給你","py":"wǒ yàn zhèng wán jiù mǎ shàng dǎ gěi nǐ","id":"Begitu selesai verifikasi aku langsung telepon"}],"grammar":["ba","yinwei","le"],"task":{"id":"Jelaskan kepada tim produksi kenapa sebuah mesin berhenti, kapan pulih, dan solusi sementara yang kamu tawarkan."}},{"id":"f_interview_equipment_eng","dom":"fab","lv":5,"title":{"zh":"設備工程師面試","id":"Wawancara posisi insinyur peralatan","en":"Interview for an equipment engineer position"},"goal":{"id":"Setelah ini kamu bisa menjawab pertanyaan wawancara umum untuk posisi insinyur peralatan di pabrik semikonduktor."},"lines":[{"sp":"A","zh":"請先做個簡單的自我介紹。","py":"qǐng xiān zuò ge jiǎn dān de zì wǒ jiè shào","id":"Silakan perkenalkan diri dengan singkat dulu.","en":"Please start with a brief self-introduction."},{"sp":"B","zh":"好的，面試官您好，我叫阿迪，是印尼人，目前就讀設備工程系，今年即將畢業。","py":"hǎo de miàn shì guān nín hǎo wǒ jiào ā dí shì yìn ní rén mù qián jiù dú shè bèi gōng chéng xì jīn nián jí jiāng bì yè","id":"Baik, selamat siang pewawancara, nama saya Adi, orang Indonesia, saat ini kuliah di jurusan teknik peralatan dan tahun ini akan lulus.","en":"Yes. Hello, interviewer. My name is Adi, I'm Indonesian, currently studying equipment engineering, and I graduate this year."},{"sp":"A","zh":"你為什麼想應徵設備工程師？","py":"nǐ wèi shén me xiǎng yìng zhēng shè bèi gōng chéng shī","id":"Kenapa kamu ingin melamar sebagai insinyur peralatan?","en":"Why do you want to apply for an equipment engineer position?"},{"sp":"B","zh":"因為我對機台的運作很有興趣，也希望能在半導體產業累積經驗。","py":"yīn wèi wǒ duì jī tái de yùn zuò hěn yǒu xìng qù yě xī wàng néng zài bàn dǎo tǐ chǎn yè lěi jī jīng yàn","id":"Karena aku sangat tertarik pada cara kerja mesin dan berharap bisa mengumpulkan pengalaman di industri semikonduktor.","en":"Because I'm very interested in how the tools operate, and I hope to build experience in the semiconductor industry."},{"sp":"A","zh":"你在學校有做過相關的專題或實習嗎？","py":"nǐ zài xué xiào yǒu zuò guò xiāng guān de zhuān tí huò shí xí ma","id":"Di kampus kamu pernah mengerjakan proyek atau magang yang terkait?","en":"Have you done any related projects or internships at school?"},{"sp":"B","zh":"有，我在實驗室做過真空系統的保養，也學過怎麼判斷幫浦的異常。","py":"yǒu wǒ zài shí yàn shì zuò guò zhēn kōng xì tǒng de bǎo yǎng yě xué guò zěn me pàn duàn bāng pǔ de yì cháng","id":"Ya, di laboratorium aku pernah merawat sistem vakum dan belajar cara menilai kelainan pompa.","en":"Yes, I've done maintenance on a vacuum system in the lab and learned how to judge pump abnormalities."},{"sp":"A","zh":"假設半夜機台當機，你一個人在現場，你會怎麼處理？","py":"jiǎ shè bàn yè jī tái dāng jī nǐ yí ge rén zài xiàn chǎng nǐ huì zěn me chǔ lǐ","id":"Misalkan tengah malam mesin mati, kamu sendirian di lokasi, apa yang akan kamu lakukan?","en":"Suppose a tool crashes in the middle of the night and you're alone on site. What would you do?"},{"sp":"B","zh":"我會先確認有沒有人員安全的問題，再看警報代碼，然後通報主管，不會自己亂改參數。","py":"wǒ huì xiān què rèn yǒu méi yǒu rén yuán ān quán de wèn tí zài kàn jǐng bào dài mǎ rán hòu tōng bào zhǔ guǎn bú huì zì jǐ luàn gǎi cān shù","id":"Aku akan memastikan dulu apakah ada masalah keselamatan personel, lalu melihat kode alarm, kemudian melapor ke atasan, dan tidak akan mengubah parameter sembarangan.","en":"I'd first check for personnel safety issues, then read the alarm code, then report to my supervisor, and I wouldn't change parameters on my own."},{"sp":"A","zh":"很好。我們廠是三班制，需要輪班，這點你可以接受嗎？","py":"hěn hǎo wǒ men chǎng shì sān bān zhì xū yào lún bān zhè diǎn nǐ kě yǐ jiē shòu ma","id":"Bagus. Pabrik kami sistem tiga shift dan perlu bergilir, apakah kamu bisa menerimanya?","en":"Good. Our fab runs three shifts and you'd rotate. Can you accept that?"},{"sp":"B","zh":"可以，我知道輪班是這個行業的常態，我也會注意作息，保持體力。","py":"kě yǐ wǒ zhī dào lún bān shì zhè ge háng yè de cháng tài wǒ yě huì zhù yì zuò xí bǎo chí tǐ lì","id":"Bisa, aku tahu shift bergilir itu hal biasa di industri ini, aku juga akan menjaga pola istirahat dan stamina.","en":"Yes. I know shift rotation is normal in this industry, and I'll watch my sleep schedule and keep my energy up."},{"sp":"A","zh":"你的中文講得不錯。工作上主要用中文溝通，你有信心嗎？","py":"nǐ de zhōng wén jiǎng de bú cuò gōng zuò shàng zhǔ yào yòng zhōng wén gōu tōng nǐ yǒu xìn xīn ma","id":"Bahasa Mandarinmu bagus. Dalam pekerjaan terutama berkomunikasi dengan bahasa Mandarin, kamu percaya diri?","en":"Your Chinese is pretty good. At work we mainly communicate in Chinese. Are you confident?"},{"sp":"B","zh":"謝謝，我還在努力學。技術的名詞我都有背，聽不懂的地方我會馬上問。","py":"xiè xie wǒ hái zài nǔ lì xué jì shù de míng cí wǒ dōu yǒu bèi tīng bu dǒng de dì fāng wǒ huì mǎ shàng wèn","id":"Terima kasih, aku masih terus belajar. Istilah teknis sudah kuhafal, bagian yang tidak kupahami akan langsung kutanyakan.","en":"Thank you, I'm still working hard at it. I've memorized the technical terms, and I'll ask right away when I don't understand."},{"sp":"A","zh":"好，最後一個問題，你有什麼問題想問我們嗎？","py":"hǎo zuì hòu yí ge wèn tí nǐ yǒu shén me wèn tí xiǎng wèn wǒ men ma","id":"Baik, pertanyaan terakhir, apakah ada yang ingin kamu tanyakan kepada kami?","en":"OK, last question. Do you have any questions for us?"},{"sp":"B","zh":"想請問新進工程師會有多久的訓練期？謝謝。","py":"xiǎng qǐng wèn xīn jìn gōng chéng shī huì yǒu duō jiǔ de xùn liàn qí xiè xie","id":"Aku ingin tanya, insinyur baru mendapat masa pelatihan berapa lama? Terima kasih.","en":"I'd like to ask how long the training period is for new engineers. Thank you."}],"phrases":[{"zh":"我對機台的運作很有興趣","py":"wǒ duì jī tái de yùn zuò hěn yǒu xìng qù","id":"Aku sangat tertarik pada cara kerja mesin"},{"zh":"希望能累積經驗","py":"xī wàng néng lěi jī jīng yàn","id":"Berharap bisa mengumpulkan pengalaman"},{"zh":"我會先確認安全，再通報主管","py":"wǒ huì xiān què rèn ān quán zài tōng bào zhǔ guǎn","id":"Aku akan pastikan keselamatan dulu, lalu lapor ke atasan"},{"zh":"聽不懂的地方我會馬上問","py":"tīng bu dǒng de dì fāng wǒ huì mǎ shàng wèn","id":"Bagian yang tidak kupahami akan langsung kutanyakan"},{"zh":"請問訓練期有多久","py":"qǐng wèn xùn liàn qí yǒu duō jiǔ","id":"Permisi, masa pelatihannya berapa lama?"}],"grammar":["guo","aux","yinwei"],"task":{"id":"Berlatihlah memperkenalkan dirimu, menjelaskan alasan melamar, dan menjawab bagaimana kamu akan menangani mesin mati tengah malam."}},{"id":"f_rca_meeting","dom":"fab","lv":5,"title":{"zh":"會議中報告原因分析與對策","id":"Melaporkan analisis akar masalah dan tindakan perbaikan","en":"Summarizing a root-cause analysis in a meeting"},"goal":{"id":"Setelah ini kamu bisa merangkum analisis penyebab dan tindakan perbaikan (jangka pendek dan panjang) dalam rapat."},"lines":[{"sp":"A","zh":"好，那就請你報告一下上週良率異常的原因分析。","py":"hǎo nà jiù qǐng nǐ bào gào yí xià shàng zhōu liáng lǜ yì cháng de yuán yīn fēn xī","id":"Baik, silakan laporkan analisis penyebab kelainan yield minggu lalu.","en":"OK, please report the root-cause analysis for last week's yield excursion."},{"sp":"B","zh":"好的。簡單說，這次良率下降的主因，是蝕刻機保養後，腔體的氣體流量沒有校準好。","py":"hǎo de jiǎn dān shuō zhè cì liáng lǜ xià jiàng de zhǔ yīn shì shí kè jī bǎo yǎng hòu qiāng tǐ de qì tǐ liú liàng méi yǒu jiào zhǔn hǎo","id":"Baik. Singkatnya, penyebab utama penurunan yield kali ini adalah aliran gas di chamber mesin etching belum dikalibrasi dengan benar setelah perawatan.","en":"Yes. In short, the main cause of this yield drop is that the chamber gas flow wasn't calibrated properly after etcher maintenance."},{"sp":"A","zh":"你怎麼確定是流量的問題？有證據嗎？","py":"nǐ zěn me què dìng shì liú liàng de wèn tí yǒu zhèng jù ma","id":"Bagaimana kamu yakin itu masalah aliran? Ada buktinya?","en":"How do you know it's a flow problem? Is there evidence?"},{"sp":"B","zh":"有。我們把紀錄調出來，發現異常那幾批的流量比設定值低了大概百分之八。","py":"yǒu wǒ men bǎ jì lù diào chū lái fā xiàn yì cháng nà jǐ pī de liú liàng bǐ shè dìng zhí dī le dà gài bǎi fēn zhī bā","id":"Ada. Kami menarik catatannya dan menemukan aliran pada lot-lot abnormal itu sekitar delapan persen lebih rendah dari nilai setelan.","en":"Yes. We pulled the logs and found the flow on the abnormal lots was about eight percent below the setpoint."},{"sp":"A","zh":"那為什麼保養的時候沒有發現？","py":"nà wèi shén me bǎo yǎng de shí hòu méi yǒu fā xiàn","id":"Lalu kenapa saat perawatan tidak ketahuan?","en":"Then why wasn't it caught during maintenance?"},{"sp":"B","zh":"因為保養後的檢查表上，沒有列出流量校準這一項，所以保養人員沒有檢查。","py":"yīn wèi bǎo yǎng hòu de jiǎn chá biǎo shàng méi yǒu liè chū liú liàng jiào zhǔn zhè yí xiàng suǒ yǐ bǎo yǎng rén yuán méi yǒu jiǎn chá","id":"Karena di daftar periksa setelah perawatan tidak tercantum item kalibrasi aliran, jadi petugas perawatan tidak memeriksanya.","en":"Because the post-maintenance checklist doesn't list flow calibration, so the maintenance staff didn't check it."},{"sp":"A","zh":"所以根本原因是檢查表不完整，對嗎？","py":"suǒ yǐ gēn běn yuán yīn shì jiǎn chá biǎo bù wán zhěng duì ma","id":"Jadi akar masalahnya daftar periksa tidak lengkap, benar?","en":"So the root cause is an incomplete checklist, right?"},{"sp":"B","zh":"對。所以我們的對策分成兩部分：短期是把異常的機台重新校準，長期是修改保養檢查表。","py":"duì suǒ yǐ wǒ men de duì cè fēn chéng liǎng bù fèn duǎn qí shì bǎ yì cháng de jī tái chóng xīn jiào zhǔn cháng qí shì xiū gǎi bǎo yǎng jiǎn chá biǎo","id":"Benar. Karena itu tindakan perbaikan kami terbagi dua: jangka pendek mengkalibrasi ulang mesin yang abnormal, jangka panjang merevisi daftar periksa perawatan.","en":"Right. So our countermeasures have two parts: short term, recalibrate the affected tools; long term, revise the maintenance checklist."},{"sp":"A","zh":"短期的部分已經完成了嗎？","py":"duǎn qí de bù fèn yǐ jīng wán chéng le ma","id":"Bagian jangka pendek sudah selesai?","en":"Is the short-term part already done?"},{"sp":"B","zh":"已經完成了，校準以後良率已經回到正常水準。長期的部分，預計這個月底前改好。","py":"yǐ jīng wán chéng le jiào zhǔn yǐ hòu liáng lǜ yǐ jīng huí dào zhèng cháng shuǐ zhǔn cháng qí de bù fèn yù jì zhè ge yuè dǐ qián gǎi hǎo","id":"Sudah selesai, setelah dikalibrasi yield sudah kembali ke level normal. Bagian jangka panjang diperkirakan selesai direvisi sebelum akhir bulan ini.","en":"Done. After calibration, yield is back to normal. The long-term part should be revised before the end of this month."},{"sp":"A","zh":"好，其他幾台同型的機台也要一起檢查，避免同樣的問題再發生。","py":"hǎo qí tā jǐ tái tóng xíng de jī tái yě yào yì qǐ jiǎn chá bì miǎn tóng yàng de wèn tí zài fā shēng","id":"Baik, beberapa mesin sejenis lainnya juga harus diperiksa sekalian, supaya masalah yang sama tidak terulang.","en":"OK, the other tools of the same model should be checked too, to prevent the same problem from recurring."},{"sp":"B","zh":"了解，我會在下週一之前把檢查結果整理好，再向大家報告。","py":"liǎo jiě wǒ huì zài xià zhōu yī zhī qián bǎ jiǎn chá jié guǒ zhěng lǐ hǎo zài xiàng dà jiā bào gào","id":"Mengerti, sebelum Senin depan aku akan merapikan hasil pemeriksaannya, lalu melaporkannya ke semua orang.","en":"Understood. I'll compile the inspection results before next Monday and report back to everyone."}],"phrases":[{"zh":"主因是腔體的氣體流量沒有校準好","py":"zhǔ yīn shì qiāng tǐ de qì tǐ liú liàng méi yǒu jiào zhǔn hǎo","id":"Penyebab utamanya aliran gas chamber belum dikalibrasi dengan benar"},{"zh":"根本原因是檢查表不完整","py":"gēn běn yuán yīn shì jiǎn chá biǎo bù wán zhěng","id":"Akar masalahnya daftar periksa tidak lengkap"},{"zh":"我們的對策分成兩部分","py":"wǒ men de duì cè fēn chéng liǎng bù fèn","id":"Tindakan perbaikan kami terbagi dua bagian"},{"zh":"短期是重新校準，長期是修改檢查表","py":"duǎn qí shì chóng xīn jiào zhǔn cháng qí shì xiū gǎi jiǎn chá biǎo","id":"Jangka pendek kalibrasi ulang, jangka panjang merevisi daftar periksa"},{"zh":"避免同樣的問題再發生","py":"bì miǎn tóng yàng de wèn tí zài fā shēng","id":"Mencegah masalah yang sama terulang"}],"grammar":["yinwei","bi","ba"],"task":{"id":"Rangkum sebuah masalah di tempat kerja: penyebab utama, bukti, akar masalah, serta tindakan jangka pendek dan jangka panjang."}}];